"use client";
import React,{createContext,useContext,useEffect,useState,useId} from 'react';
import {Button} from '@/components/ui/button';
import {Input} from '@/components/ui/input';
import {Textarea} from '@/components/ui/textarea';
import {Checkbox} from '@/components/ui/checkbox';
import {Select,SelectTrigger,SelectValue,SelectContent,SelectItem} from '@/components/ui/select';
import {Tabs,TabsList,TabsTrigger,TabsContent} from '@/components/ui/tabs';
import {Toaster,toast} from 'sonner';
import {Menu,X,BriefcaseBusiness,Users,Layers,HardHat,GraduationCap,Check,Mail,Phone,MessageCircle,Bell,FileText,UserRound,Settings,ClipboardList} from 'lucide-react';
import {services,defaultContent,proposalStatuses,applicationStatuses,statusAr} from '@/lib/data';
type D=Record<string,any>;type Opt=[string,string,string?];type Spec={k:string;en:string;ar:string;type?:string;required?:boolean;full?:boolean;options?:Opt[];help?:[string,string];autoComplete?:string;minLength?:number;maxLength?:number};
const Context=createContext<any>(null);const useA=()=>useContext(Context);
async function api(path:string,method='GET',data?:any):Promise<any>{const res=await fetch(`/api/${path}`,{method,headers:method==='GET'?{}:data instanceof FormData?{}:{'Content-Type':'application/json'},...(method==='GET'?{}:{body:data instanceof FormData?data:JSON.stringify(data||{})})});const out:any=await res.json();if(!res.ok)throw new Error(out.error||'Unable to complete this action');return out;}
function LinkButton({href,children,outline=false,gold=false,small=false}:{href:string;children:React.ReactNode;outline?:boolean;gold?:boolean;small?:boolean}){return <Button asChild className={`btn ${outline?'btn-outline':''} ${gold?'btn-gold':''} ${small?'btn-small':''}`}><a href={href} target={href.startsWith('/signin-with-chatgpt')?'_top':undefined}>{children}</a></Button>}
function Action({children,onClick,outline=false,type='button',small=false,disabled=false}:{children:React.ReactNode;onClick?:()=>void;outline?:boolean;type?:'button'|'submit';small?:boolean;disabled?:boolean}){const a=useA();return <Button type={type} disabled={disabled||a.busy} onClick={onClick} className={`btn ${outline?'btn-outline':''} ${small?'btn-small':''}`}>{children}</Button>}
function Field({spec,data,set}:{spec:Spec;data:D;set:(d:D)=>void}){const {tr,ar}=useA(),fid=useId();const value=data[spec.k]??'';const change=(v:any)=>set({...data,[spec.k]:v});return <div className={`field ${spec.full?'full':''}`}><label htmlFor={fid}>{tr(spec.en,spec.ar)}{spec.required&&<span className="required"> *</span>}</label>{spec.options?<Select value={String(value)||undefined} onValueChange={change} required={spec.required} dir={ar?'rtl':'ltr'}><SelectTrigger id={fid} className="w-full mt-2 h-auto py-3 text-base"><SelectValue placeholder={tr('Select an option','اختر من القائمة')}/></SelectTrigger><SelectContent>{spec.options.map(([v,en,arabic])=><SelectItem key={v} value={v}>{tr(en,arabic||en)}</SelectItem>)}</SelectContent></Select>:spec.type==='textarea'?<Textarea id={fid} value={value} onChange={e=>change(e.target.value)} required={spec.required} maxLength={20000}/>:<Input id={fid} type={spec.type||'text'} value={value} onChange={e=>change(e.target.value)} required={spec.required} min={spec.type==='number'?0:undefined} maxLength={spec.maxLength||2000} minLength={spec.minLength} autoComplete={spec.autoComplete||(spec.type==='email'?'email':spec.type==='password'?'current-password':spec.type==='tel'?'tel':spec.k==='name'?'name':undefined)}/>} {spec.help&&<p className="help">{tr(...spec.help)}</p>}</div>}
function Fields({specs,data,set}:{specs:Spec[];data:D;set:(d:D)=>void}){return <div className="field-grid">{specs.map(s=><Field key={s.k} spec={s} data={data} set={set}/>)}</div>}
function Tick({checked,onChange,children}:{checked:boolean;onChange:(v:boolean)=>void;children:React.ReactNode}){const cid=useId();return <div className="check"><Checkbox id={cid} checked={checked} onCheckedChange={v=>onChange(v===true)} className="mt-1 size-[18px]"/><label htmlFor={cid}>{children}</label></div>}
function Tag({status}:{status:string}){const {ar}=useA();return <span className={`tag ${['Accepted','Hired','Published','Proposal Sent'].includes(status)?'gold':''}`}>{ar?statusAr[status]||status:status}</span>}
function Header({page}:{page:string}){const {tr,ar,setAr,session}=useA(),[open,setOpen]=useState(false);const links=[['services','Services','خدماتنا'],['about','About Apex','عن أبيكس'],['vacancies','Vacancies','الوظائف'],['partnerships','Partnerships','الشراكات']];return <header><div className="wrap"><nav className="nav" aria-label={tr('Main navigation','التنقل الرئيسي')}><Brand/><div className="navlinks">{links.map(([p,en,a])=><a className={page===p?'active':''} key={p} href={`/${p}`}>{tr(en,a)}</a>)}</div><div className="nav-actions"><button className="lang" onClick={()=>setAr(!ar)} aria-label={tr('Switch to Arabic','التغيير إلى الإنجليزية')}>{ar?'English':'العربية'}</button><a className="nav-signin" href={session?.user?['admin','recruiter'].includes(session.user.role)?'/admin':'/dashboard':'/account'}>{session?.user?tr('My dashboard','لوحة التحكم'):tr('Sign in','تسجيل الدخول')}</a><button className="menu-toggle" onClick={()=>setOpen(!open)} aria-expanded={open} aria-label={tr('Navigation menu','قائمة التنقل')}>{open?<X size={23}/>:<Menu size={23}/>}</button></div></nav></div>{open&&<nav className="mobile-nav">{links.map(([p,en,a])=><a key={p} href={`/${p}`}>{tr(en,a)}</a>)}<a href="/contact">{tr('Contact','تواصل معنا')}</a><a href={session?.user?'/dashboard':'/account'}>{tr('My account','حسابي')}</a></nav>}</header>}
function Brand(){return <a className="brand" href="/" aria-label="Apex Global Services LLC home"><img className="apex-logo" src="/apex-logo.png" width="1254" height="1254" alt="Apex Global Services LLC"/></a>}
function Footer(){const {tr,content}=useA();return <footer className="footer"><div className="wrap"><div className="footer-grid"><div><Brand/><p>{tr('Recruitment, outsourcing, and workforce solutions. Connecting businesses with talent and people with opportunities.','حلول توظيف وتعهيد وقوى عاملة تربط الشركات بالكفاءات والأفراد بالفرص.')}</p></div><div><h3>{tr('For your business','لشركتك')}</h3><a href="/services">{tr('Our services','خدماتنا')}</a><a href="/request-proposal">{tr('Request a proposal','اطلب عرضاً')}</a><a href="/partnerships">{tr('Training partnerships','شراكات التدريب')}</a><a href="/about">{tr('About Apex','عن أبيكس')}</a></div><div><h3>{tr('Find your opportunity','ابحث عن فرصتك')}</h3><a href="/vacancies">{tr('Explore vacancies','استكشف الوظائف')}</a><a href="/account?role=candidate">{tr('Create a candidate profile','أنشئ ملف مرشح')}</a><a href="/contact">{tr('Contact us','تواصل معنا')}</a>{content.email&&<a href={`mailto:${content.email}`}>{content.email}</a>}</div></div><div className="footer-bottom"><span>© {new Date().getFullYear()} Apex Global Services LLC</span><span><a style={{display:'inline',marginInlineEnd:20,fontSize:12}} href="/privacy">{tr('Privacy Policy','سياسة الخصوصية')}</a><a style={{display:'inline',fontSize:12}} href="/terms">{tr('Terms','الشروط')}</a></span><span>{tr('Egypt & the MENA region','مصر والشرق الأوسط وشمال أفريقيا')}</span></div></div></footer>}
function PageHeader({en,ar,desc,descAr,eyebrow,eyebrowAr}:{en:string;ar:string;desc?:string;descAr?:string;eyebrow?:string;eyebrowAr?:string}){const {tr}=useA();return <section className="page-header"><div className="wrap">{eyebrow&&<div className="eyebrow">{tr(eyebrow,eyebrowAr||eyebrow)}</div>}<h1>{tr(en,ar)}</h1>{desc&&<p>{tr(desc,descAr||desc)}</p>}</div></section>}
const serviceIcons=[BriefcaseBusiness,Layers,Users,HardHat,GraduationCap];
function ServiceCards(){const {tr,content}=useA();return <div className="service-grid">{services.map((s,i)=>{const Icon=serviceIcons[i];return <article className="service-card" key={s.id}><div className="flex justify-between items-center mb-6"><Icon size={28} strokeWidth={1.4} color="#94763c"/>{s.expanding&&<span className="tag gold">{tr('Expanding service','خدمة نتوسع بها')}</span>}</div><h3>{tr(s.en,s.ar)}</h3><p>{tr(content[`service_${s.id}`]||s.desc,content[`service_${s.id}_ar`]||s.descAr)}</p><a className="text-link" href={`/services#${s.id}`}>{tr('Explore this service','تعرف على الخدمة')}</a></article>})}</div>}
function Home(){const {tr,ar,content}=useA();const custom=content.headline!==defaultContent.headline||content.headlineAr!==defaultContent.headlineAr;return <><section className="hero"><div className="wrap"><div className="hero-inner"><div className="hero-copy"><div className="eyebrow">{tr('People · Operations · Growth','الكوادر · العمليات · النمو')}</div><h1>{custom?tr(content.headline,content.headlineAr):ar?<>الكوادر المناسبة.<br/>الدعم المناسب.<br/><em>مجال للنمو.</em></>:<>The right people.<br/>The right support.<br/><em>Room to grow.</em></>}</h1><p>{tr(content.intro,content.introAr)}</p><div className="button-row"><LinkButton href="/request-proposal">{tr('Request a Proposal','اطلب عرضاً')}</LinkButton><LinkButton href="/vacancies" outline>{tr('Explore Vacancies','استكشف الوظائف')}</LinkButton></div></div><div className="hero-art"><img src="/apex-architecture.webp" width="768" height="512" alt={tr('Conceptual architectural sculpture in navy and gold','تكوين معماري رمزي باللون الكحلي والذهبي')}/><div className="art-caption">{tr('From Egypt. Built for broader possibilities.','من مصر، نحو فرص أوسع.')}</div></div></div><div className="hero-bottom"><strong>Apex Global Services LLC</strong><span>{tr('Egypt & the MENA region','مصر والشرق الأوسط وشمال أفريقيا')}</span><span>{tr('Your next team starts here','هنا يبدأ فريقك القادم')}</span></div></div></section><section className="section"><div className="wrap"><div className="eyebrow">{tr('What we do','ما نقدمه')}</div><div className="section-head"><h2>{tr('People solutions, shaped around your business.','حلول كوادر تناسب احتياجات شركتك.')}</h2><p>{tr('Choose the support you need today. We’ll work with you on the right scope, responsibilities, and delivery arrangement.','اختر الدعم الذي تحتاجه اليوم. نتعاون معك لتحديد نطاق العمل والمسؤوليات وآلية التنفيذ المناسبة.')}</p></div><ServiceCards/></div></section><section className="section section-muted"><div className="wrap split"><div className="dark-panel"><div className="eyebrow">{tr('Where we focus','مجالات تركيزنا')}</div><h2>{tr('Practical support. A clear understanding of your work.','دعم عملي. وفهم واضح لطبيعة عملك.')}</h2><p>{tr('From customer-facing teams to technical projects, the starting point is always the same: understand the role, define the requirements, and find the right fit.','من فرق التعامل مع العملاء إلى المشروعات الفنية، نبدأ دائماً بفهم الوظيفة وتحديد المتطلبات والبحث عن الكفاءات المناسبة.')}</p></div><div><h3>{tr('Industries & functions','القطاعات والوظائف')}</h3><div className="industry-list">{[['BPO & call centres','التعهيد ومراكز الاتصال'],['Customer service','خدمة العملاء'],['Telesales','المبيعات الهاتفية'],['Appointment setting','تحديد المواعيد'],['Back-office operations','العمليات المكتبية'],['Industrial & contracting','الصناعة والمقاولات']].map(([en,a])=><div key={en}>{tr(en,a)}</div>)}</div></div></div></section><section className="section"><div className="wrap"><div className="eyebrow">{tr('Working with Apex','التعاون مع أبيكس')}</div><div className="section-head"><h2>{tr('A clear path from need to next step.','خطوات واضحة من الاحتياج إلى التنفيذ.')}</h2></div><div className="process">{[['01','Tell us what you need','شاركنا احتياجاتك','Share the roles, functions, timing and business context in a proposal request.','حدد الوظائف والمهام والجدول الزمني وسياق العمل في طلب العرض.'],['02','Align the approach','نتفق على الأسلوب','We review your brief, clarify the details and prepare a tailored proposal.','نراجع طلبك ونوضح التفاصيل ونعد عرضاً يناسب احتياجاتك.'],['03','Build the engagement','نبدأ التعاون','Agree the scope and responsibilities, then take the next step together.','نتفق على النطاق والمسؤوليات ثم نتخذ الخطوة التالية معاً.']].map(([n,en,a,d,da])=><div key={n}><div className="process-num">{n}</div><h3>{tr(en,a)}</h3><p>{tr(d,da)}</p></div>)}</div></div></section><section className="section pt-0"><div className="wrap"><div className="candidate-banner"><div><div className="eyebrow">{tr('For candidates','للمرشحين')}</div><h2>{tr('Your skills deserve the right opportunity.','مهاراتك تستحق الفرصة المناسبة.')}</h2></div><div><p>{tr('Explore open roles, create one reusable profile, and keep track of every application. Join our talent pool for future opportunities.','استكشف الوظائف وأنشئ ملفاً واحداً قابلاً لإعادة الاستخدام وتابع طلباتك. انضم لقاعدة الكفاءات للفرص المستقبلية.')}</p><div className="button-row"><LinkButton href="/vacancies">{tr('Explore vacancies','استكشف الوظائف')}</LinkButton><LinkButton href="/account?role=candidate" outline>{tr('Create a profile','أنشئ ملفك')}</LinkButton></div></div></div></div></section><section className="section pt-0"><div className="wrap partnership"><div className="partnership-aside">{tr('Good training opens a door. The right employment partnership helps people walk through it.','التدريب الجيد يفتح باباً. وشراكة التوظيف المناسبة تساعد الخريجين على عبوره.')}</div><div><div className="eyebrow">{tr('Training partnerships','شراكات التدريب')}</div><h2>{tr('Turn graduate skills into career possibilities.','حوّل مهارات الخريجين إلى فرص مهنية.')}</h2><p>{tr('We work with training organisations to understand their graduates’ strengths and connect suitable candidates with employer requirements.','نتعاون مع جهات التدريب لفهم مهارات الخريجين وربط المرشحين المناسبين باحتياجات أصحاب العمل.')}</p><a className="text-link" href="/partnerships">{tr('Discuss a training partnership','ناقش شراكة تدريب')}</a></div></div></section><section className="cta"><div className="wrap cta-inner"><h2>{tr('Let’s build your next team.','لنبنِ فريقك القادم.')}</h2><LinkButton href="/request-proposal" gold>{tr('Request a Proposal','اطلب عرضاً')}</LinkButton></div></section></>}
function About(){const {tr,content}=useA();return <><PageHeader en="A people business. A practical approach." ar="شركة تهتم بالكوادر. وأسلوب عملي." eyebrow="About Apex" eyebrowAr="عن أبيكس"/><section className="section"><div className="wrap split"><div><h2>{tr('Connecting talent with what comes next.','نربط الكفاءات بالخطوة القادمة.')}</h2><p className="white-space">{tr(content.about,content.aboutAr)}</p><p>{tr('We focus on Egypt and MENA, supporting businesses serving local and international markets. Every engagement starts with the client’s real needs and a clear agreement on what we will deliver.','نركز على مصر والشرق الأوسط وشمال أفريقيا، ونخدم الشركات العاملة في الأسواق المحلية والدولية. يبدأ كل تعاون باحتياجات العميل الفعلية واتفاق واضح على المطلوب تقديمه.')}</p></div><div className="dark-panel"><div className="eyebrow">{tr('Our approach','أسلوبنا')}</div>{[['Understand the business','نفهم طبيعة العمل','Define the roles, priorities and expectations before sourcing.','نحدد الوظائف والأولويات والتوقعات قبل البحث.'],['Keep the process clear','عملية واضحة','Transparent scope, screening and communication at every stage.','نطاق واضح وتقييم وتواصل مستمر في كل مرحلة.'],['Respect people and information','نحترم الأشخاص وبياناتهم','Private profiles, appropriate consent and controlled access.','ملفات خاصة وموافقة مناسبة وتحكم في الوصول.']].map(([en,a,d,da])=><div className="bullet" key={en}><Check size={19}/><div><h3>{tr(en,a)}</h3><p>{tr(d,da)}</p></div></div>)}</div></div></section><section className="section section-muted"><div className="wrap reading"><div className="eyebrow">{tr('Founder','المؤسس')}</div><h2>Samy Salama</h2><p>{tr('Samy brings experience in recruitment, team leadership and business operations, including leading customer service and sales teams on Sutherland’s AT&T account and managing operations at ElAraby Contracts. His background in sociology and data analysis informs an approach that combines an understanding of people with attention to performance.','يجمع سامي خبرة في التوظيف وقيادة الفرق وإدارة الأعمال، بما في ذلك قيادة فرق خدمة العملاء والمبيعات في حساب AT&T لدى Sutherland وإدارة العمليات في ElAraby Contracts. وتدعم خلفيته في علم الاجتماع وتحليل البيانات أسلوباً يجمع فهم الأشخاص والاهتمام بالأداء.')}</p><LinkButton href="/request-proposal">{tr('Work with Apex','تعاون مع أبيكس')}</LinkButton></div></section></>}
function Services(){const {tr,content}=useA();return <><PageHeader en="The support that fits your business." ar="الدعم الذي يناسب شركتك." desc="Recruit directly, extend your team, or discuss a managed business function. Each service has a clear role." descAr="وظف مباشرة أو ادعم فريقك أو ناقش إدارة وظيفة تشغيلية. لكل خدمة نطاق واضح." eyebrow="Our services" eyebrowAr="خدماتنا"/><section className="section"><div className="wrap">{services.map(s=><article id={s.id} key={s.id} className="service-detail"><div>{s.expanding&&<span className="tag gold mb-4">{tr('Expanding service line','خدمة نتوسع بها')}</span>}<h2>{tr(s.en,s.ar)}</h2></div><div><p>{tr(content[`service_${s.id}`]||s.detail,content[`service_${s.id}_ar`]||s.detailAr)}</p><ul>{(tr(s.items,s.itemsAr) as string[]).map(item=><li key={item}>{item}</li>)}</ul><LinkButton small href={s.id==='training'?'/partnerships':`/request-proposal?service=${s.id}`}>{tr('Discuss your requirements','ناقش متطلباتك')}</LinkButton></div></article>)}</div></section></>}
function Empty({title,desc,href,label}:{title:[string,string];desc:[string,string];href?:string;label?:[string,string]}){const {tr}=useA();return <div className="empty"><h3>{tr(...title)}</h3><p>{tr(...desc)}</p>{href&&label&&<LinkButton href={href}>{tr(...label)}</LinkButton>}</div>}
const arrangements:Opt[]=[['On-site','On-site','من مقر العمل'],['Hybrid','Hybrid','هجين'],['Remote','Remote','عن بعد']];const employment:Opt[]=[['Full-time','Full-time','دوام كامل'],['Part-time','Part-time','دوام جزئي'],['Contract','Contract','تعاقد'],['Temporary','Temporary','مؤقت']];
function Vacancies(){const {tr,jobs,session,mutate}=useA(),[f,setF]=useState<D>({});useEffect(()=>{const change=(e:any)=>setF(e.detail);window.addEventListener('apex-vacancy-search',change);return()=>window.removeEventListener('apex-vacancy-search',change)},[]);const values=(key:string):Opt[]=>[['all',tr('All','الكل')],...Array.from(new Set(jobs.map((j:any)=>j.data[key]).filter(Boolean))).map((v:any)=>[v,v] as Opt)];const filtered=jobs.filter((j:any)=>{const d=j.data;return (!f.keyword||`${d.title} ${d.requirements} ${d.responsibilities}`.toLowerCase().includes(f.keyword.toLowerCase()))&&['location','industry','employmentType','arrangement','language'].every(k=>!f[k]||f[k]==='all'||d[k]===f[k])});return <><PageHeader en="Find your next opportunity." ar="ابحث عن فرصتك القادمة." desc="Explore current vacancies and apply with your Apex candidate profile." descAr="استكشف الوظائف الحالية وتقدم باستخدام ملف المرشح الخاص بك." eyebrow="Careers" eyebrowAr="الوظائف"/><section className="section"><div className="wrap"><div className="filters"><Field spec={{k:'keyword',en:'Role or keyword',ar:'الوظيفة أو كلمة البحث'}} data={f} set={setF}/>{[['location','Location','الموقع'],['industry','Industry / department','القطاع أو القسم'],['employmentType','Employment type','نوع التوظيف']].map(([k,en,ar])=><Field key={k} spec={{k,en,ar,options:values(k)}} data={f} set={setF}/>)}</div><div className="filters-extra"><Field spec={{k:'arrangement',en:'Work arrangement',ar:'نظام العمل',options:[['all','All arrangements','كل الأنظمة'],...arrangements]}} data={f} set={setF}/><Field spec={{k:'language',en:'Language requirements',ar:'متطلبات اللغة',options:values('language')}} data={f} set={setF}/></div>{filtered.length?filtered.map((j:any)=><article key={j.id} className="job-card"><h3><a href={`/vacancies/${j.id}`}>{tr(j.data.title,j.data.titleAr||j.data.title)}</a></h3>{!j.data.confidential&&j.data.company&&<p>{j.data.company}</p>}<div className="job-meta">{[j.data.location,j.data.arrangement,j.data.employmentType,j.data.language].filter(Boolean).map((m:string)=><span key={m} className="tag">{m}</span>)}</div><p>{tr(j.data.summary||j.data.responsibilities.slice(0,180),j.data.summaryAr||j.data.summary||j.data.responsibilities.slice(0,180))}</p><div className="button-row"><LinkButton href={`/vacancies/${j.id}`} small>{tr('View role & apply','عرض الوظيفة والتقديم')}</LinkButton>{session?.user?.role==='candidate'&&<Action outline small onClick={()=>mutate(()=>api('saved','POST',{vacancyId:j.id}),tr('Vacancy saved','تم حفظ الوظيفة'))}>{tr('Save vacancy','احفظ الوظيفة')}</Action>}</div></article>):<Empty title={[jobs.length?'No matching vacancies':'No vacancies published yet',jobs.length?'لا توجد وظائف مطابقة':'لم تُنشر وظائف بعد']} desc={['Join our talent pool and keep a reusable profile ready for future opportunities.','انضم لقاعدة الكفاءات وجهّز ملفك للفرص المستقبلية.']} href="/account?role=candidate" label={['Join the talent pool','انضم لقاعدة الكفاءات']}/>}</div></section></>}
function JobDetail({jobId}:{jobId:string}){const {tr,session,mutate}=useA(),[job,setJob]=useState<any>(null),[err,setErr]=useState(''),[answers,setAnswers]=useState<D>({}),[consent,setConsent]=useState(false),[share,setShare]=useState(false),[sent,setSent]=useState(false);useEffect(()=>{api(`vacancies/${jobId}`).then(setJob).catch(e=>setErr(e.message))},[jobId]);if(err)return <section className="section wrap"><div className="notice error">{err}</div><LinkButton href="/vacancies">{tr('Back to vacancies','العودة للوظائف')}</LinkButton></section>;if(!job)return <div className="loading">{tr('Loading vacancy…','جارٍ تحميل الوظيفة…')}</div>;const d=job.data;return <><PageHeader en={d.title} ar={d.titleAr||d.title} desc={d.confidential?tr('Confidential recruitment','توظيف سري'):d.company||''}/><section className="section"><div className="wrap split items-start"><article><div className="job-meta">{[d.location,d.arrangement,d.employmentType,d.language].filter(Boolean).map((v:string)=><span className="tag" key={v}>{v}</span>)}</div>{d.shifts&&<p>{tr('Shifts: ','الورديات: ')}{d.shifts}</p>}{d.deadline&&<p>{tr('Application deadline: ','آخر موعد للتقديم: ')}{d.deadline}</p>}{d.salaryAuthorised&&d.salary&&<p>{tr('Compensation: ','التعويضات: ')}{d.salary}</p>}<h3>{tr('Responsibilities','المسؤوليات')}</h3><p className="white-space">{tr(d.responsibilities,d.responsibilitiesAr||d.responsibilities)}</p><h3>{tr('Requirements','المتطلبات')}</h3><p className="white-space">{tr(d.requirements,d.requirementsAr||d.requirements)}</p></article><div className="form-panel"><h3>{tr('Apply for this vacancy','تقدم لهذه الوظيفة')}</h3>{sent?<div className="notice success">{tr('Application received. Track it in your dashboard.','تم استلام طلبك. تابع حالته في لوحة التحكم.')}<div className="actions"><LinkButton href="/dashboard" small>{tr('My applications','طلباتي')}</LinkButton></div></div>:session?.user?.role==='candidate'?<form onSubmit={e=>{e.preventDefault();mutate(async()=>{await api('applications','POST',{vacancyId:job.id,answers,consent,sharingConsent:share});setSent(true)},tr('Application received','تم استلام الطلب'))}}><p>{tr('Your current profile and CV will be saved with this application. Later profile edits will not change it.','يُحفظ ملفك وسيرتك الحالية مع الطلب، ولن تغير تعديلات الملف اللاحقة هذا الطلب.')}</p>{!session.user.profile.cvId&&<div className="notice warning">{tr('Upload your CV and complete your profile first.','ارفع سيرتك الذاتية وأكمل ملفك أولاً.')} <a className="text-link" href="/dashboard?tab=profile">{tr('Edit profile','تعديل الملف')}</a></div>}{(d.questions||[]).map((q:string)=><Field key={q} spec={{k:q,en:q,ar:q,type:'textarea',required:true}} data={answers} set={setAnswers}/>)}<Tick checked={consent} onChange={setConsent}>{tr('I consent to Apex processing this application under the Privacy Policy.','أوافق على معالجة أبيكس لهذا الطلب وفق سياسة الخصوصية.')}</Tick><Tick checked={share} onChange={setShare}>{tr('I also consent to Apex sharing this application profile and CV with a hiring client for this role.','أوافق أيضاً على مشاركة هذا الملف والسيرة مع العميل الذي يوظف لهذه الوظيفة.')}</Tick><Action type="submit" disabled={!consent||!session.user.profile.cvId}>{tr('Apply Now','تقدم الآن')}</Action></form>:<><p>{tr('Create a candidate account or sign in to apply using your profile and CV.','أنشئ حساب مرشح أو سجل الدخول للتقديم باستخدام ملفك وسيرتك.')}</p><LinkButton href="/account?role=candidate">{tr('Register / sign in','سجل حساباً / الدخول')}</LinkButton></>}</div></div></section></>}
function SignOut(){const {tr,session,mutate}=useA();return <button type="button" className="text-link" onClick={()=>mutate(async()=>{if(session?.authProvider==='Email')await api('auth/signout','POST',{});location.href=session?.platformAuthenticated?'/signout-with-chatgpt?return_to=%2F':'/'},tr('Signed out','تم تسجيل الخروج'))}>{tr('Sign out','تسجيل الخروج')}</button>}
function EmailAccountForm({role,next,existing=false}:{role:string;next:string;existing?:boolean}){
 const {tr,session,mutate}=useA(),[mode,setMode]=useState(existing?'signup':'signin'),[d,setD]=useState<D>({email:existing?session?.user?.email||'':'',name:existing?session?.user?.name||'':'',phone:existing?session?.user?.profile?.phone||'':'',company:existing?session?.user?.profile?.company||'':'',password:'',consent:false,marketingConsent:false}),[message,setMessage]=useState('');
 const submit=()=>mutate(async()=>{const out=await api(`auth/${mode==='reset'?'reset':mode}`,'POST',{...d,role,next});setD({...d,password:''});if(mode==='signin')location.href=out.registered?(next==='proposal'?'/request-proposal':'/dashboard'):`/account?role=${role}${next==='proposal'?'&next=proposal':''}`;else setMessage(mode==='reset'?tr('If an account exists for this email, a password-reset link has been sent.','إذا وجد حساب بهذا البريد، تم إرسال رابط إعادة تعيين كلمة المرور.'):out.confirmationRequired?tr('Check your inbox to confirm your email. Open the link in this browser to finish creating your Apex account.','تحقق من بريدك لتأكيد عنوانك. افتح الرابط في هذا المتصفح لإكمال إنشاء حساب أبيكس.'):tr('Email account confirmed. Continue to your dashboard.','تم تأكيد حساب البريد. انتقل إلى لوحة التحكم.'))},tr(mode==='signin'?'Signed in':'Request completed',mode==='signin'?'تم تسجيل الدخول':'تم إتمام الطلب'));
 return <div><div className="button-row mb-6">{!existing&&[['signin','Sign in','تسجيل الدخول'],['signup','Create account','إنشاء حساب']].map(([m,en,ar])=><Action key={m} outline={mode!==m} small onClick={()=>{setMode(m);setMessage('')}}>{tr(en,ar)}</Action>)}</div><h3>{tr(mode==='signup'?(existing?'Add email sign-in':'Create your Apex account'):mode==='reset'?'Reset your password':'Sign in with email',mode==='signup'?(existing?'أضف تسجيل الدخول بالبريد':'أنشئ حساب أبيكس'):mode==='reset'?'إعادة تعيين كلمة المرور':'تسجيل الدخول بالبريد')}</h3>{message?<div role="status" className="notice success">{message}<div className="actions"><Action small outline onClick={()=>{setMode('signin');setMessage('')}}>{tr('Back to sign in','العودة إلى تسجيل الدخول')}</Action>{mode==='signup'&&<Action small outline onClick={()=>mutate(()=>api('auth/resend','POST',{email:d.email,role,next}),tr('Confirmation email requested','تم طلب بريد التأكيد'))}>{tr('Resend confirmation','إعادة إرسال التأكيد')}</Action>}</div></div>:<form onSubmit={e=>{e.preventDefault();submit()}}><Fields specs={[{k:'email',en:'Email address',ar:'البريد الإلكتروني',type:'email',required:true},...(mode==='signup'?[{k:'name',en:'Full name / contact person',ar:'الاسم الكامل / مسؤول التواصل',required:true},{k:'phone',en:'Phone number with country code',ar:'رقم الهاتف مع رمز الدولة',type:'tel',required:true},...(role==='client'?[{k:'company',en:'Company name',ar:'اسم الشركة',required:true}]:[])]:[]),...(mode!=='reset'?[{k:'password',en:'Password',ar:'كلمة المرور',type:'password',required:true,minLength:mode==='signup'?10:1,maxLength:128,autoComplete:mode==='signup'?'new-password':'current-password',help:mode==='signup'?['Use at least 10 characters.','استخدم ١٠ أحرف على الأقل.'] as [string,string]:undefined}]:[])]} data={d} set={setD}/>{mode==='signup'&&<><Tick checked={d.consent} onChange={v=>setD({...d,consent:v})}>{tr('I agree to the Terms and Privacy Policy.','أوافق على الشروط وسياسة الخصوصية.')} <a href="/privacy" className="text-link">{tr('Read policies','اقرأ السياسات')}</a></Tick><Tick checked={d.marketingConsent} onChange={v=>setD({...d,marketingConsent:v})}>{tr('Optional marketing updates from Apex.','تحديثات تسويقية اختيارية من أبيكس.')}</Tick></>}<Action type="submit" disabled={mode==='signup'&&!d.consent}>{tr(mode==='signup'?'Create email account':mode==='reset'?'Send reset link':'Sign in',mode==='signup'?'إنشاء حساب بالبريد':mode==='reset'?'أرسل رابط الاستعادة':'تسجيل الدخول')}</Action>{mode==='signin'&&<div className="actions"><Action small outline onClick={()=>{setMode('reset');setMessage('')}}>{tr('Forgot password?','نسيت كلمة المرور؟')}</Action></div>}</form>}</div>
}
function Account(){
 const {tr,session,loading,mutate}=useA(),[role,setRole]=useState('candidate'),[d,setD]=useState<D>({name:'',phone:'',company:'',consent:false,marketingConsent:false}),[next,setNext]=useState(''),[authMode,setAuthMode]=useState(''),[exchange,setExchange]=useState(false),[authError,setAuthError]=useState(''),[addEmail,setAddEmail]=useState(false),[newPassword,setNewPassword]=useState('');
 useEffect(()=>{const p=new URLSearchParams(location.search);setRole(p.get('role')==='client'?'client':'candidate');setNext(p.get('next')||'');setAuthMode(p.get('auth')||'');const code=p.get('code');if(code){setExchange(true);api('auth/exchange','POST',{code}).then(()=>{p.delete('code');location.replace('/account?'+p.toString())}).catch((e:any)=>{setExchange(false);setAuthError(e.message);p.delete('code');history.replaceState(null,'','/account?'+p.toString())})}},[]);
 if(loading||exchange)return <div className="loading">{tr(exchange?'Confirming your email…':'Loading account…',exchange?'جارٍ تأكيد بريدك…':'جارٍ تحميل الحساب…')}</div>;
 return <><PageHeader en="Your Apex account." ar="حسابك لدى أبيكس." desc="Manage proposals, applications and your private profile." descAr="تابع العروض وطلبات التوظيف وملفك الخاص."/><section className="section"><div className="wrap narrow">{authError&&<div role="alert" className="notice error">{authError}</div>}{authMode==='recovery'&&session?.authProvider==='Email'?<form className="form-panel" onSubmit={e=>{e.preventDefault();mutate(async()=>{await api('auth/password','POST',{password:newPassword});setNewPassword('');location.href='/dashboard'},tr('Password updated','تم تحديث كلمة المرور'))}}><h2>{tr('Choose a new password','اختر كلمة مرور جديدة')}</h2><div className="field"><label htmlFor="new-password">{tr('New password','كلمة المرور الجديدة')}</label><Input id="new-password" type="password" autoComplete="new-password" required minLength={10} maxLength={128} value={newPassword} onChange={e=>setNewPassword(e.target.value)}/><p className="help">{tr('Use at least 10 characters.','استخدم ١٠ أحرف على الأقل.')}</p></div><Action type="submit">{tr('Save password','احفظ كلمة المرور')}</Action></form>:session?.user?<div className="form-panel"><h2>{tr('Welcome back','مرحباً بعودتك')}, {session.user.name}</h2>{authMode==='confirmed'&&<p role="status" className="notice success">{tr('Your email is confirmed.','تم تأكيد بريدك الإلكتروني.')}</p>}<p>{tr('Your account is ready. Continue to your dashboard.','حسابك جاهز. انتقل إلى لوحة التحكم.')}</p><LinkButton href={['admin','recruiter'].includes(session.user.role)?'/admin':next==='proposal'?'/request-proposal':'/dashboard'}>{tr('Open dashboard','افتح لوحة التحكم')}</LinkButton><div className="actions"><SignOut/>{session.authProvider==='ChatGPT'&&session.emailAuthConfigured&&<Action small outline onClick={()=>setAddEmail(!addEmail)}>{tr('Add email sign-in','أضف تسجيل الدخول بالبريد')}</Action>}</div>{addEmail&&<div className="mt-8"><EmailAccountForm role={session.user.role==='client'?'client':'candidate'} next={next} existing/></div>}</div>:<><div className="role-cards">{[['client','For businesses','للشركات','Request tailored proposals and manage your engagement with Apex.','اطلب عروضاً مخصصة وتابع تعاونك مع أبيكس.'],['candidate','For candidates','للمرشحين','Save your profile, apply for roles and track your applications.','احفظ ملفك وتقدم للوظائف وتابع طلباتك.']].map(([r,en,a,de,da])=><button key={r} onClick={()=>setRole(r)} className="account-card text-start" style={{borderColor:role===r?'#b79a5b':'#dce2e9',background:role===r?'#faf8f2':'white'}} aria-pressed={role===r}><h3>{tr(en,a)}</h3><p>{tr(de,da)}</p><span className="tag">{role===r?tr('Selected','تم الاختيار'):tr('Choose account type','اختر نوع الحساب')}</span></button>)}</div><div className="form-panel mt-6">{session?.authenticated?<form onSubmit={e=>{e.preventDefault();mutate(async()=>{await api('register','POST',{...d,role});location.href=next==='proposal'?'/request-proposal':'/dashboard'},tr('Account created','تم إنشاء الحساب'))}}><h3>{tr('Complete your registration','أكمل تسجيل حسابك')}</h3><p className="muted">{session.identity.email}</p><Fields specs={[{k:'name',en:'Full name / contact person',ar:'الاسم الكامل / مسؤول التواصل',required:true},{k:'phone',en:'Phone number with country code',ar:'رقم الهاتف مع رمز الدولة',type:'tel',required:true},...(role==='client'?[{k:'company',en:'Company name',ar:'اسم الشركة',required:true}]:[])]} data={d} set={setD}/><Tick checked={d.consent} onChange={v=>setD({...d,consent:v})}>{tr('I agree to the Terms and Privacy Policy.','أوافق على الشروط وسياسة الخصوصية.')} <a className="text-link" href="/privacy">{tr('Read policies','اقرأ السياسات')}</a></Tick><Tick checked={d.marketingConsent} onChange={v=>setD({...d,marketingConsent:v})}>{tr('Optional marketing updates from Apex.','تحديثات تسويقية اختيارية من أبيكس.')}</Tick><Action type="submit" disabled={!d.consent}>{tr('Create my Apex account','أنشئ حساب أبيكس')}</Action></form>:<>{session?.emailAuthConfigured&&<><EmailAccountForm role={role} next={next}/><hr className="my-8"/></>}{!session?.emailAuthConfigured&&<p role="status">{tr('Account service is being configured. Please contact Apex for assistance.','يجري إعداد خدمة الحسابات. تواصل مع أبيكس للمساعدة.')}</p>}</>}</div></>}</div></section></>}

