const requestFields:Spec[]=[{k:'company',en:'Company name',ar:'اسم الشركة',required:true},{k:'name',en:'Contact person',ar:'مسؤول التواصل',required:true},{k:'email',en:'Business email',ar:'البريد الإلكتروني للعمل',type:'email',required:true},{k:'phone',en:'Telephone',ar:'الهاتف',type:'tel',required:true},{k:'needs',en:'Your business needs',ar:'احتياجات شركتك',type:'textarea',full:true,required:true},{k:'roles',en:'Required roles or functions',ar:'الوظائف أو المهام المطلوبة',required:true},{k:'headcount',en:'Headcount',ar:'عدد الأفراد',type:'number',required:true},{k:'location',en:'Location',ar:'الموقع',required:true},{k:'arrangement',en:'Work arrangement',ar:'نظام العمل',options:arrangements,required:true},{k:'languages',en:'Language requirements',ar:'متطلبات اللغة'},{k:'experience',en:'Experience requirements',ar:'متطلبات الخبرة'},{k:'startDate',en:'Target start date',ar:'تاريخ البدء المستهدف',type:'date'},{k:'budget',en:'Expected budget (optional)',ar:'الميزانية المتوقعة (اختياري)'}];
const conditional:Record<string,Spec[]>={recruitment:[{k:'hiringTimeline',en:'Hiring timeline',ar:'الجدول الزمني للتوظيف'},{k:'compensation',en:'Compensation range (if available)',ar:'نطاق التعويضات إن توفر'},{k:'screening',en:'Screening expectations',ar:'توقعات تقييم المرشحين',type:'textarea',full:true}],outsourcing:[{k:'operatingHours',en:'Operating hours & time zone',ar:'ساعات التشغيل والمنطقة الزمنية'},{k:'systems',en:'Systems used',ar:'الأنظمة المستخدمة'},{k:'workload',en:'Expected workload',ar:'حجم العمل المتوقع'},{k:'performance',en:'Performance expectations',ar:'توقعات الأداء'},{k:'delivery',en:'Preferred delivery arrangement',ar:'آلية التنفيذ المفضلة',type:'textarea',full:true}],augmentation:[{k:'skills',en:'Required skills',ar:'المهارات المطلوبة'},{k:'duration',en:'Engagement duration',ar:'مدة التعاون'},{k:'operatingHours',en:'Working hours',ar:'ساعات العمل'},{k:'reporting',en:'Reporting structure',ar:'هيكل التقارير'},{k:'equipment',en:'Equipment / system-access requirements',ar:'متطلبات المعدات والوصول للأنظمة',type:'textarea',full:true}],industrial:[{k:'trades',en:'Required trades & qualifications',ar:'الحرف والمؤهلات المطلوبة'},{k:'deployment',en:'Deployment schedule',ar:'جدول الانتشار'},{k:'duration',en:'Project duration',ar:'مدة المشروع'},{k:'shifts',en:'Shifts',ar:'الورديات'},{k:'siteSupport',en:'Accommodation, transportation & PPE needs',ar:'احتياجات السكن والنقل ومعدات الوقاية',type:'textarea',full:true}]};
function FileUpload({ids,setIds,label}:{ids:string[];setIds:(ids:string[])=>void;label?:[string,string]}){const {tr,mutate,session}=useA(),[names,setNames]=useState<D>({}),fileId=useId();return <div className="field"><label htmlFor={fileId}>{tr(...(label||['Attachments (optional)','المرفقات (اختياري)']))}</label><input id={fileId} type="file" accept=".pdf,.doc,.docx" disabled={!session?.user} onChange={e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>10*1024*1024){toast.error(tr('Maximum file size: 10 MB','الحد الأقصى لحجم الملف: 10 ميجابايت'));return}mutate(async()=>{const fd=new FormData();fd.append('file',f);const out=await api('files','POST',fd);setIds([...ids,out.id]);setNames({...names,[out.id]:out.name});e.target.value=''},tr('File uploaded privately','تم رفع الملف بشكل خاص'))}}/><p className="help">{tr('PDF, DOC or DOCX. Maximum 10 MB per file. Files are private.','PDF أو DOC أو DOCX. حد أقصى 10 ميجابايت لكل ملف. الملفات خاصة.')}</p>{!session?.user&&<p className="help">{tr('Sign in to add attachments. Your other information is preserved.','سجل الدخول لإضافة المرفقات. يتم الاحتفاظ بالمعلومات الأخرى.')}</p>}{ids.map((fid,i)=><div key={fid} className="flex gap-3 items-center"><a className="file-link" href={`/api/files/${fid}`}>{names[fid]||tr(`Attachment ${i+1}`,`مرفق ${i+1}`)}</a><button type="button" className="text-xs underline" onClick={()=>setIds(ids.filter(x=>x!==fid))}>{tr('Remove from form','إزالة من النموذج')}</button></div>)}</div>}
function RequestProposal({initial,onSaved}:{initial?:any;onSaved?:()=>void}){const {tr,session,mutate}=useA(),[d,setD]=useState<D>({service:'recruitment',fileIds:[]}),[ready,setReady]=useState(false),[result,setResult]=useState('');useEffect(()=>{if(initial)setD(initial.data);else{try{const saved=JSON.parse(localStorage.getItem('apex-proposal-draft')||'null'),p=new URLSearchParams(location.search);setD(saved||{service:p.get('service')||'recruitment',company:session?.user?.profile?.company||'',name:session?.user?.name||'',email:session?.user?.email||'',fileIds:[]})}catch{}}setReady(true)},[initial]);useEffect(()=>{if(ready&&!initial)localStorage.setItem('apex-proposal-draft',JSON.stringify(d))},[d,ready,initial]);useEffect(()=>{const change=(e:any)=>setD(prev=>({...prev,...e.detail}));window.addEventListener('apex-stage-proposal',change);return()=>window.removeEventListener('apex-stage-proposal',change)},[]);useEffect(()=>{if(session?.user&&!initial)setD(prev=>({...prev,company:prev.company||session.user.profile.company||'',name:prev.name||session.user.name,email:prev.email||session.user.email}))},[session?.user?.id]);const send=(submit:boolean)=>{if(!session?.user){localStorage.setItem('apex-proposal-draft',JSON.stringify(d));location.href='/account?role=client&next=proposal';return}if(session.user.role!=='client'){toast.error(tr('Use a client account to submit requests.','استخدم حساب عميل لإرسال الطلبات.'));return}mutate(async()=>{const out=await api(initial?`requests/${initial.id}`:'requests',initial?'PUT':'POST',{...d,submit});setResult(submit?tr('Your request has been submitted. Find your reference and progress in the client dashboard.','تم إرسال طلبك. تابع الرقم المرجعي والحالة في لوحة العميل.'):tr('Draft saved to your client dashboard.','تم حفظ المسودة في لوحة العميل.'));if(submit&&!initial)localStorage.removeItem('apex-proposal-draft');onSaved?.()},tr(submit?'Request submitted':'Draft saved',submit?'تم إرسال الطلب':'تم حفظ المسودة'))};return <>{!initial&&<PageHeader en="Tell us what your business needs." ar="شاركنا احتياجات شركتك." desc="Start with a brief. We’ll clarify the details and prepare a tailored proposal." descAr="ابدأ بطلب مختصر. نوضح التفاصيل ونعد عرضاً مخصصاً." eyebrow="Request a proposal" eyebrowAr="اطلب عرضاً"/>}<section className={initial?'':'section'}><div className={initial?'':'wrap narrow'}><form className="form-panel" onSubmit={e=>{e.preventDefault();send(true)}}>{result?<div className="notice success">{result}<div className="actions"><LinkButton href="/dashboard" small>{tr('Open client dashboard','افتح لوحة العميل')}</LinkButton></div></div>:<><Field spec={{k:'service',en:'Which service do you need?',ar:'ما الخدمة التي تحتاجها؟',required:true,options:serviceOptions}} data={d} set={setD}/><Fields specs={requestFields} data={d} set={setD}/>{conditional[d.service]&&<><h3 className="mt-6">{tr('Service requirements','متطلبات الخدمة')}</h3><Fields specs={conditional[d.service]} data={d} set={setD}/></>}<Field spec={{k:'notes',en:'Additional notes',ar:'ملاحظات إضافية',type:'textarea'}} data={d} set={setD}/><FileUpload ids={d.fileIds||[]} setIds={ids=>setD({...d,fileIds:ids})}/><div className="notice">{tr('No fixed pricing: each proposal is based on your scope. Submitting a request does not create a contract.','لا توجد أسعار ثابتة: يعتمد كل عرض على نطاق عملك. إرسال الطلب لا ينشئ عقداً.')}</div><div className="button-row"><Action type="submit">{session?.user?tr('Submit request','أرسل الطلب'):tr('Continue to register & submit','تابع للتسجيل والإرسال')}</Action>{session?.user?.role==='client'&&<Action outline onClick={()=>send(false)}>{tr('Save draft','احفظ المسودة')}</Action>}</div></>}</form></div></section></>}
function Enquiry({training=false}:{training?:boolean}){const {tr,mutate}=useA(),[d,setD]=useState<D>({type:training?'training':'business',consent:false}),[sent,setSent]=useState('');const specs:Spec[]=[...(training?[{k:'organisation',en:'Organisation name',ar:'اسم المؤسسة',required:true}]:[]),{k:'name',en:'Contact name',ar:'اسم مسؤول التواصل',required:true},{k:'email',en:'Email',ar:'البريد الإلكتروني',type:'email',required:true},{k:'phone',en:'Telephone',ar:'الهاتف',type:'tel'},...(training?[{k:'specialisations',en:'Training specialisations',ar:'تخصصات التدريب',required:true},{k:'skills',en:'Graduate skill sets',ar:'مهارات الخريجين',required:true},{k:'locations',en:'Graduate locations',ar:'مواقع الخريجين',required:true},{k:'graduateNumbers',en:'Approximate graduate numbers',ar:'عدد الخريجين التقريبي',type:'number'}]:[]),{k:'message',en:training?'Partnership notes':'Your enquiry',ar:training?'ملاحظات الشراكة':'استفسارك',type:'textarea',full:true,required:true}];return <form className="form-panel" onSubmit={e=>{e.preventDefault();mutate(async()=>{const out=await api('enquiries','POST',d);setSent(out.reference)},tr('Enquiry received','تم استلام الاستفسار'))}}>{sent?<div className="notice success">{tr('Thank you. Your enquiry reference is ','شكراً لك. الرقم المرجعي للاستفسار هو ')}<strong>{sent}</strong></div>:<>{!training&&<Field spec={{k:'type',en:'I’m contacting Apex as a…',ar:'أتواصل مع أبيكس بصفتي…',options:[['business','Business','شركة'],['candidate','Candidate','مرشح'],['training','Training organisation','جهة تدريب']]}} data={d} set={setD}/>}<Fields specs={specs} data={d} set={setD}/>{!training&&d.type==='training'&&<Fields specs={[{k:'organisation',en:'Organisation',ar:'المؤسسة',required:true},{k:'specialisations',en:'Training specialisations',ar:'تخصصات التدريب',required:true},{k:'skills',en:'Graduate skills',ar:'مهارات الخريجين',required:true},{k:'locations',en:'Locations',ar:'المواقع',required:true}]} data={d} set={setD}/>}<div aria-hidden="true" className="visually-hidden"><label>Leave empty<input tabIndex={-1} autoComplete="off" value={d.websiteTrap||''} onChange={e=>setD({...d,websiteTrap:e.target.value})}/></label></div><Tick checked={d.consent} onChange={v=>setD({...d,consent:v})}>{tr('I consent to Apex using these details to respond to my enquiry.','أوافق على استخدام أبيكس لهذه التفاصيل للرد على استفساري.')} <a href="/privacy" className="text-link">{tr('Privacy Policy','سياسة الخصوصية')}</a></Tick><Action type="submit" disabled={!d.consent}>{tr('Send enquiry','أرسل الاستفسار')}</Action></>}</form>}
function Partnerships(){const {tr}=useA();return <><PageHeader en="Skills taught. Opportunities connected." ar="مهارات تُكتسب. وفرص تتصل بها." desc="A partnership route for training organisations and their graduates." descAr="مسار شراكة لجهات التدريب وخريجيها." eyebrow="Training-to-employment" eyebrowAr="من التدريب إلى التوظيف"/><section className="section"><div className="wrap split items-start"><div><h2>{tr('Let’s understand your graduates.','لنتعرف على خريجيك.')}</h2><p>{tr('Tell us what your graduates are trained to do, where they’re based and what roles interest them. We’ll explore how their skills align with employer requirements.','أخبرنا بمهارات خريجيك ومواقعهم والوظائف التي تهمهم. نستكشف مدى توافق مهاراتهم مع متطلبات أصحاب العمل.')}</p>{[['Share the specialisations you teach','شاركنا تخصصات التدريب'],['Map graduate skills and language proficiency','حدد مهارات الخريجين ومستويات اللغة'],['Explore suitable roles and screening requirements','استكشف الوظائف ومتطلبات التقييم']].map(([e,a])=><div className="bullet" key={e}><Check size={19}/><span>{tr(e,a)}</span></div>)}<div className="notice">{tr('A partnership enquiry starts a discussion. Employment depends on available roles, requirements and selection.','يبدأ استفسار الشراكة نقاشاً. يعتمد التوظيف على الوظائف المتاحة ومتطلباتها ونتائج الاختيار.')}</div></div><Enquiry training/></div></section></>}
function Contact(){const {tr,content}=useA();return <><PageHeader en="Let’s start a conversation." ar="لنبدأ الحوار." desc="Business enquiry, career question or training partnership—we’ll point you in the right direction." descAr="استفسار عمل أو سؤال مهني أو شراكة تدريب، نساعدك على اختيار المسار المناسب."/><section className="section"><div className="wrap split items-start"><div><h2>{tr('Contact Apex','تواصل مع أبيكس')}</h2><p>{tr('For a detailed business brief, use the proposal request. For general questions, send an enquiry here.','للاحتياجات التفصيلية للشركات استخدم طلب العرض. للأسئلة العامة أرسل استفسارك هنا.')}</p><div className="button-row mb-8"><LinkButton href="/request-proposal">{tr('Request a proposal','اطلب عرضاً')}</LinkButton><LinkButton href="/vacancies" outline>{tr('Find a vacancy','ابحث عن وظيفة')}</LinkButton></div>{content.email&&<div className="bullet"><Mail size={20}/><a href={`mailto:${content.email}`}>{content.email}</a></div>}{content.phone&&<div className="bullet"><Phone size={20}/><a href={`tel:${content.phone}`}>{content.phone}</a></div>}{content.whatsapp&&<div className="bullet"><MessageCircle size={20}/><a href={`https://wa.me/${content.whatsapp.replace(/\D/g,'')}`} target="_blank" rel="noopener noreferrer">WhatsApp</a></div>}{[content.linkedin,content.facebook].filter(Boolean).map((url:string)=><div key={url}><a className="text-link" href={url} target="_blank" rel="noopener noreferrer">{url.includes('linkedin')?'LinkedIn':'Facebook'}</a></div>)}{!content.email&&!content.phone&&<p className="help">{tr('Direct contact details are awaiting company setup. You can send an enquiry using this form.','بيانات التواصل المباشر بانتظار إعداد الشركة. يمكنك إرسال استفسارك بهذا النموذج.')}</p>}</div><Enquiry/></div></section></>}
const candidateFields:Spec[]=[{k:'name',en:'Full name',ar:'الاسم الكامل',required:true},{k:'phone',en:'Telephone',ar:'الهاتف',type:'tel',required:true},{k:'location',en:'Location',ar:'الموقع',required:true},{k:'education',en:'Education',ar:'التعليم'},{k:'experience',en:'Work experience',ar:'الخبرة العملية',type:'textarea',full:true},{k:'skills',en:'Skills',ar:'المهارات',type:'textarea'},{k:'languages',en:'Languages & proficiency',ar:'اللغات ومستوياتها',type:'textarea'},{k:'preferredRoles',en:'Preferred roles',ar:'الوظائف المفضلة'},{k:'preferredArrangement',en:'Preferred work arrangement',ar:'نظام العمل المفضل',options:arrangements},{k:'availability',en:'Availability / start date',ar:'موعد التفرغ أو البدء'}];
const clientFields:Spec[]=[{k:'company',en:'Company name',ar:'اسم الشركة',required:true},{k:'industry',en:'Industry',ar:'القطاع'},{k:'website',en:'Website',ar:'الموقع الإلكتروني',type:'url'},{k:'name',en:'Contact person',ar:'مسؤول التواصل',required:true},{k:'jobTitle',en:'Job title',ar:'المسمى الوظيفي'},{k:'phone',en:'Telephone',ar:'الهاتف',type:'tel'},{k:'operatingLocations',en:'Operating locations',ar:'مواقع التشغيل',type:'textarea',full:true}];
function Profile(){const {tr,session,mutate}=useA(),[d,setD]=useState<D>({...session.user.profile,name:session.user.name});return <div className="panel"><h2>{tr(session.user.role==='client'?'Company profile':'Candidate profile',session.user.role==='client'?'ملف الشركة':'ملف المرشح')}</h2><p className="muted">{tr('Verified sign-in email: ','بريد تسجيل الدخول المتحقق منه: ')}{session.user.email}</p><form onSubmit={e=>{e.preventDefault();mutate(()=>api('profile','PUT',d),tr('Profile saved','تم حفظ الملف'))}}><Fields specs={session.user.role==='client'?clientFields:candidateFields} data={d} set={setD}/>{session.user.role==='candidate'&&<><FileUpload ids={d.cvId?[d.cvId]:[]} setIds={ids=>setD({...d,cvId:ids.at(-1)||''})} label={['CV','السيرة الذاتية']}/><Tick checked={d.talentPool===true} onChange={v=>setD({...d,talentPool:v})}>{tr('Join the talent pool for future opportunities.','الانضمام لقاعدة الكفاءات للفرص المستقبلية.')}</Tick></>}<Action type="submit">{tr('Save profile','احفظ الملف')}</Action></form></div>}
function AccountSettings(){const {tr,session,mutate}=useA(),[d,setD]=useState<D>({...session.user.profile,name:session.user.name});return <><div className="panel"><h2>{tr('Notification preferences','تفضيلات الإشعارات')}</h2><p>{tr('Essential account and activity notifications remain available in your dashboard. Marketing consent is separate.','تظل إشعارات الحساب والأنشطة الأساسية متاحة في لوحة التحكم. الموافقة التسويقية منفصلة.')}</p><form onSubmit={e=>{e.preventDefault();mutate(()=>api('profile','PUT',d),tr('Preferences saved','تم حفظ التفضيلات'))}}><Tick checked={d.emailNotifications!==false} onChange={v=>setD({...d,emailNotifications:v})}>{tr('Email me activity notifications when email delivery is configured.','إرسال إشعارات الأنشطة بالبريد عند إعداد خدمة الإرسال.')}</Tick><Tick checked={d.marketingConsent===true} onChange={v=>setD({...d,marketingConsent:v})}>{tr('Optional marketing updates.','تحديثات تسويقية اختيارية.')}</Tick><div className="notice">{session.emailConfigured?tr('Transactional email is configured.','تم إعداد البريد الإلكتروني للمعاملات.'):tr('Transactional email is not configured. Your in-dashboard notifications are active.','لم يتم إعداد البريد الإلكتروني للمعاملات. إشعارات لوحة التحكم مفعلة.')}</div><Action type="submit">{tr('Save preferences','احفظ التفضيلات')}</Action></form></div><div className="panel"><h2>{tr('Your data & account','بياناتك وحسابك')}</h2><p>{tr('Download your records or ask Apex to process a personal-data or account-deletion request. Deletion requests are reviewed by an administrator.','حمّل سجلاتك أو اطلب من أبيكس معالجة طلب بيانات شخصية أو حذف حساب. يراجع مسؤول النظام طلبات الحذف.')}</p><div className="button-row"><LinkButton href="/api/export" small outline>{tr('Download my data','حمّل بياناتي')}</LinkButton><Action small outline onClick={()=>mutate(()=>api('privacy','POST',{type:'access'}),tr('Data request received','تم استلام طلب البيانات'))}>{tr('Request data assistance','اطلب مساعدة ببياناتك')}</Action><Action small outline onClick={()=>mutate(()=>api('privacy','POST',{type:'delete'}),tr('Deletion request received for review','تم استلام طلب الحذف للمراجعة'))}>{tr('Request account deletion','اطلب حذف الحساب')}</Action></div><div className="notice">{tr('Your sign-in provider manages your login and account recovery. Deleting your Apex profile removes your Apex records and blocks access; it does not delete your provider account.','تدير خدمة تسجيل الدخول هويتك واستعادة حسابك. حذف ملف أبيكس يزيل سجلاتك ويمنع الوصول؛ ولا يحذف حسابك لدى خدمة الدخول.')}</div><SignOut/></div></>}
function Notifications({items}:{items:any[]}){const {tr,ar,mutate}=useA();return <div className="panel"><div className="record-head"><h2>{tr('Notifications','الإشعارات')}</h2><Action outline small onClick={()=>mutate(()=>api('notifications','PUT',{}),tr('Notifications marked as read','تم تحديد الإشعارات كمقروءة'))}>{tr('Mark all read','تحديد الكل كمقروء')}</Action></div>{!items.length?<p>{tr('No notifications yet.','لا توجد إشعارات بعد.')}</p>:items.map(n=><div className={`notification ${!n.read?'unread':''}`} key={n.id}><strong>{ar?n.title_ar:n.title}</strong><p>{ar?n.body_ar:n.body}</p><span className="muted">{new Date(n.created).toLocaleString(ar?'ar-EG':'en-GB')}</span></div>)}</div>}
function Info({data}:{data:D}){const {tr}=useA();const all=[...requestFields,...Object.values(conditional).flat(),...candidateFields,...clientFields,{k:'informationRequest',en:'Information requested by Apex',ar:'المعلومات المطلوبة من أبيكس'},{k:'additionalInfo',en:'Additional information',ar:'معلومات إضافية'},{k:'notes',en:'Additional notes',ar:'ملاحظات إضافية'}];const specs=Array.from(new Map(all.map(s=>[s.k,s])).values());return <dl className="grid gap-4 sm:grid-cols-2 my-6">{specs.filter(s=>data[s.k]).map(s=><div key={s.k}><dt className="muted">{tr(s.en,s.ar)}</dt><dd className="white-space text-sm m-0">{String(data[s.k])}</dd></div>)}</dl>}
function Files({ids,label}:{ids:string[];label?:string}){const {tr}=useA();return <>{(ids||[]).map((fid,i)=><a key={fid} className="file-link" href={`/api/files/${fid}`}>{label||tr(`Download attachment ${i+1}`,`تحميل المرفق ${i+1}`)}</a>)}</>}
function downloadText(name:string,body:string){const url=URL.createObjectURL(new Blob([body],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
function ProposalCard({p,requestId,isLatest}:{p:any;requestId:string;isLatest:boolean}){const {tr,mutate}=useA(),[message,setMessage]=useState<D>({message:''});return <div className="record"><div className="record-head"><h3>{p.data.title}</h3><span className="tag">{tr('Version','النسخة')} {p.data.version}</span></div><p className="muted">{new Date(p.created).toLocaleDateString()}</p><div className="pre">{p.data.body}</div><Files ids={p.data.fileIds||[]}/><div className="actions"><Action small outline onClick={()=>downloadText(`Apex-Proposal-v${p.data.version}.txt`,`Apex Global Services LLC\n${p.data.title}\nVersion ${p.data.version}\n\n${p.data.body}`)}>{tr('Download proposal text','تحميل نص العرض')}</Action></div>{p.data.response&&<div className="notice">{tr('Your response: ','ردك: ')}{p.data.response.action==='accept'?tr('Accepted','تم القبول'):tr('Revision requested','تم طلب تعديل')}{p.data.response.message&&<p>{p.data.response.message}</p>}</div>}{isLatest&&!p.data.response&&<><div className="notice warning">{tr('Accepting records your response to this proposal. It does not create a binding contract or initiate payment.','القبول يسجل ردك على العرض، ولا ينشئ عقداً ملزماً أو يبدأ أي دفع.')}</div><Field spec={{k:'message',en:'Revision notes (required for revisions)',ar:'ملاحظات التعديل (مطلوبة لطلب التعديل)',type:'textarea'}} data={message} set={setMessage}/><div className="button-row"><Action small onClick={()=>mutate(()=>api('request-response','POST',{requestId,proposalId:p.id,action:'accept'}),tr('Acceptance recorded','تم تسجيل القبول'))}>{tr('Accept proposal','قبول العرض')}</Action><Action small outline disabled={!message.message.trim()} onClick={()=>mutate(()=>api('request-response','POST',{requestId,proposalId:p.id,action:'revise',message:message.message}),tr('Revision requested','تم طلب التعديل'))}>{tr('Request revisions','اطلب تعديلات')}</Action></div></>}</div>}
function RequestCard({r,proposals,adminView=false}:{r:any;proposals:any[];adminView?:boolean}){const {tr,mutate}=useA(),[d,setD]=useState<D>({status:r.status,informationRequest:r.data.informationRequest||'',additionalInfo:'',fileIds:[]});const versions=proposals.filter(p=>p.parent===r.id).sort((a,b)=>b.data.version-a.data.version);return <div className="record"><div className="record-head"><div><h3>{r.data.company}</h3><p className="muted">{r.data.reference} · {tr(services.find(s=>s.id===r.data.service)?.en||'Other',services.find(s=>s.id===r.data.service)?.ar||'أخرى')}</p></div><Tag status={r.status}/></div><details className="details"><summary>{tr('View request details','عرض تفاصيل الطلب')}</summary><Info data={r.data}/><Files ids={r.data.fileIds||[]}/>{!adminView&&r.status==='Draft'?<RequestProposal initial={r}/>:!adminView&&<form className="mt-5" onSubmit={e=>{e.preventDefault();mutate(()=>api(`requests/${r.id}`,'PUT',d),tr('Information added','تمت إضافة المعلومات'))}}><Field spec={{k:'additionalInfo',en:'Add information for Apex',ar:'أضف معلومات لأبيكس',type:'textarea',required:true}} data={d} set={setD}/><FileUpload ids={d.fileIds} setIds={ids=>setD({...d,fileIds:ids})}/><Action type="submit" small>{tr('Send information','إرسال المعلومات')}</Action></form>}{adminView&&<><form className="mt-5" onSubmit={e=>{e.preventDefault();mutate(()=>api(`requests/${r.id}`,'PUT',d),tr('Request updated','تم تحديث الطلب'))}}><Field spec={{k:'status',en:'Request status',ar:'حالة الطلب',options:proposalStatuses.filter(s=>s!=='Accepted').map(s=>[s,s,statusAr[s]])}} data={d} set={setD}/><Field spec={{k:'informationRequest',en:'Information to request / client-facing message',ar:'المعلومات المطلوبة / رسالة للعميل',type:'textarea'}} data={d} set={setD}/><Action type="submit" small>{tr('Update request','تحديث الطلب')}</Action></form><InternalNotes parent={r.id}/><ProposalEditor requestId={r.id}/></>}</details>{versions.length>0&&<details className="details" open={!adminView}><summary>{tr('Proposals & versions','العروض والنسخ')} ({versions.length})</summary>{versions.map((p,i)=>adminView?<div className="record" key={p.id}><h3>{p.data.title} · {tr('Version','النسخة')} {p.data.version}</h3><div className="pre">{p.data.body}</div><Files ids={p.data.fileIds||[]}/>{p.data.response&&<div className="notice">{p.data.response.action==='accept'?tr('Client accepted','قبل العميل العرض'):tr('Client requested revisions','طلب العميل تعديلات')}: {p.data.response.message}</div>}</div>:<ProposalCard key={p.id} p={p} requestId={r.id} isLatest={i===0}/>)}</details>}</div>}
function ProposalEditor({requestId}:{requestId:string}){const {tr,mutate}=useA(),[d,setD]=useState<D>({requestId,title:'Service proposal',body:'Scope of services:\n\nRoles / functions and headcount:\n\nDelivery arrangement and responsibilities:\n\nTimeline:\n\nCommercial terms (to be agreed):\n\nNext steps:',fileIds:[]});return <details className="details"><summary>{tr('Prepare / send a new proposal version','إعداد / إرسال نسخة عرض جديدة')}</summary><form onSubmit={e=>{e.preventDefault();mutate(()=>api('proposals','POST',d),tr('Proposal version shared','تم إرسال نسخة العرض'))}} className="mt-5"><Fields specs={[{k:'title',en:'Proposal title',ar:'عنوان العرض',required:true},{k:'body',en:'Editable proposal',ar:'العرض القابل للتحرير',type:'textarea',full:true,required:true}]} data={d} set={setD}/><FileUpload ids={d.fileIds} setIds={ids=>setD({...d,fileIds:ids})}/><Action type="submit" small>{tr('Send proposal version','إرسال نسخة العرض')}</Action></form></details>}
function InternalNotes({parent}:{parent:string}){const {tr,dash,mutate}=useA(),[d,setD]=useState<D>({body:''});return <details className="details"><summary>{tr('Private internal notes','ملاحظات داخلية خاصة')}</summary>{(dash.notes||[]).filter((n:any)=>n.parent===parent).map((n:any)=><div className="notice" key={n.id}>{n.body}<div className="muted">{new Date(n.created).toLocaleString()}</div></div>)}<form onSubmit={e=>{e.preventDefault();mutate(async()=>{await api('notes','POST',{parent,...d});setD({body:''})},tr('Internal note saved','تم حفظ الملاحظة الداخلية'))}} className="mt-4"><Field spec={{k:'body',en:'Internal note',ar:'ملاحظة داخلية',type:'textarea',required:true}} data={d} set={setD}/><Action type="submit" small outline>{tr('Save private note','حفظ ملاحظة خاصة')}</Action></form></details>}
function ApplicationCard({a,staffView=false}:{a:any;staffView?:boolean}){const {tr,mutate,session,dash}=useA(),[d,setD]=useState<D>({status:a.status,interview:a.details?.interview||'',message:a.details?.message||'',clientId:''});return <div className="record"><div className="record-head"><div><h3>{tr(a.vacancy.title,a.vacancy.titleAr||a.vacancy.title)}</h3><p className="muted">{staffView?a.snapshot.name:''} · {new Date(a.created).toLocaleDateString()}</p></div><Tag status={a.status}/></div>{a.details?.interview&&<div className="notice"><strong>{tr('Interview details','تفاصيل المقابلة')}</strong><p className="white-space">{a.details.interview}</p></div>}{a.details?.message&&<p>{a.details.message}</p>}<details className="details"><summary>{tr('Submitted application','الطلب المقدم')}</summary><p>{a.snapshot.name} · {a.snapshot.email}</p><Info data={a.snapshot.profile}/><Files ids={[a.snapshot.profile.cvId]} label={tr('Download submitted CV','تحميل السيرة المقدمة')}/>{Object.entries(a.snapshot.answers||{}).map(([q,v])=><div className="notice" key={q}><strong>{q}</strong><p>{String(v)}</p></div>)}{!staffView&&!['Hired','Not Selected','Withdrawn'].includes(a.status)&&<Action small outline onClick={()=>mutate(()=>api(`applications/${a.id}`,'PUT',{status:'Withdrawn'}),tr('Application withdrawn','تم سحب الطلب'))}>{tr('Withdraw application','سحب الطلب')}</Action>}{staffView&&<><form className="mt-6" onSubmit={e=>{e.preventDefault();mutate(()=>api(`applications/${a.id}`,'PUT',d),tr('Application updated','تم تحديث الطلب'))}}><Fields specs={[{k:'status',en:'Application status',ar:'حالة الطلب',options:applicationStatuses.map(s=>[s,s,statusAr[s]])},{k:'interview',en:'Interview details (date, time, location / meeting link)',ar:'تفاصيل المقابلة (التاريخ والوقت والموقع أو الرابط)',type:'textarea',required:d.status==='Interview Scheduled'},{k:'message',en:'Candidate-facing update',ar:'تحديث يظهر للمرشح',type:'textarea',full:true}]} data={d} set={setD}/><Action type="submit" small>{tr('Save status & notify candidate','حفظ الحالة وإشعار المرشح')}</Action></form><InternalNotes parent={a.id}/>{session.user.role==='admin'&&<details className="details"><summary>{tr('Share with a client','مشاركة مع عميل')}</summary>{a.snapshot.sharingConsent?<><Field spec={{k:'clientId',en:'Client account',ar:'حساب العميل',options:(dash.users||[]).filter((u:any)=>u.role==='client').map((u:any)=>[u.id,u.profile.company||u.name])}} data={d} set={setD}/><Action small disabled={!d.clientId} onClick={()=>mutate(()=>api('share','POST',{applicationId:a.id,clientId:d.clientId}),tr('Application shared with authorised client','تمت مشاركة الطلب مع العميل المخول'))}>{tr('Share consented application','مشاركة الطلب بالموافقة')}</Action></>:<div className="notice warning">{tr('This candidate has not consented to client sharing for this application.','لم يوافق المرشح على مشاركة هذا الطلب مع العملاء.')}</div>}</details>}</>}</details></div>}
function CandidateDashboard(){const {tr,dash}=useA(),[tab,setTab]=useState('overview');useEffect(()=>{const t=new URLSearchParams(location.search).get('tab');if(t==='profile')setTab(t)},[]);const applications=dash.applications||[],saved=dash.saved||[];return <Tabs className="dash-tabs" value={tab} onValueChange={setTab}><TabsList>{[['overview','Overview','نظرة عامة'],['applications','Applications','الطلبات'],['saved','Saved vacancies','الوظائف المحفوظة'],['profile','My profile','ملفي'],['notifications','Notifications','الإشعارات'],['settings','Settings','الإعدادات']].map(([v,en,a])=><TabsTrigger key={v} value={v}>{tr(en,a)}</TabsTrigger>)}</TabsList><TabsContent value="overview"><div className="stat-grid"><Stat value={applications.length} label={['Applications','طلبات التوظيف']}/><Stat value={applications.filter((a:any)=>a.status==='Under Review').length} label={['Under review','قيد المراجعة']}/><Stat value={applications.filter((a:any)=>a.status==='Interview Scheduled').length} label={['Interviews','المقابلات']}/><Stat value={saved.length} label={['Saved vacancies','الوظائف المحفوظة']}/></div><div className="panel"><h2>{tr('Your next steps','خطواتك القادمة')}</h2><p>{tr('Keep your profile and CV ready, then apply for roles that match your skills.','جهّز ملفك وسيرتك ثم تقدم للوظائف التي تناسب مهاراتك.')}</p><div className="button-row"><Action onClick={()=>setTab('profile')}>{tr('Complete my profile','أكمل ملفي')}</Action><LinkButton href="/vacancies" outline>{tr('Browse vacancies','تصفح الوظائف')}</LinkButton></div></div><Notifications items={(dash.notifications||[]).slice(0,3)}/></TabsContent><TabsContent value="applications"><div className="panel"><h2>{tr('Application history','سجل الطلبات')}</h2>{applications.length?applications.map((a:any)=><ApplicationCard key={a.id} a={a}/>):<Empty title={['No applications yet','لا توجد طلبات بعد']} desc={['Complete your profile and CV, then explore vacancies.','أكمل ملفك وسيرتك ثم استكشف الوظائف.']} href="/vacancies" label={['Explore vacancies','استكشف الوظائف']}/>}</div></TabsContent><TabsContent value="saved"><div className="panel"><h2>{tr('Saved vacancies','الوظائف المحفوظة')}</h2>{saved.length?saved.map((r:any)=><SavedCard key={r.id} r={r}/>):<p>{tr('You haven’t saved a vacancy yet.','لم تحفظ أي وظيفة بعد.')}</p>}</div></TabsContent><TabsContent value="profile"><Profile/></TabsContent><TabsContent value="notifications"><Notifications items={dash.notifications||[]}/></TabsContent><TabsContent value="settings"><AccountSettings/></TabsContent></Tabs>}
function SavedCard({r}:{r:any}){const {tr,mutate}=useA();return <div className="record"><h3>{r.data.title}</h3><div className="actions"><LinkButton href={`/vacancies/${r.parent}`} small>{tr('View vacancy','عرض الوظيفة')}</LinkButton><Action outline small onClick={()=>mutate(()=>api(`saved/${r.id}`,'DELETE'),tr('Saved vacancy removed','تمت إزالة الوظيفة المحفوظة'))}>{tr('Remove','إزالة')}</Action></div></div>}
function Stat({value,label}:{value:number;label:[string,string]}){const {tr}=useA();return <div className="stat"><strong>{value}</strong><span>{tr(...label)}</span></div>}
function ClientDashboard(){const {tr,dash}=useA(),[tab,setTab]=useState('overview'),requests=dash.requests||[],proposals=dash.proposals||[];return <Tabs className="dash-tabs" value={tab} onValueChange={setTab}><TabsList>{[['overview','Overview','نظرة عامة'],['requests','Requests & proposals','الطلبات والعروض'],['candidates','Shared candidates','المرشحون المشاركون'],['profile','Company profile','ملف الشركة'],['notifications','Notifications','الإشعارات'],['settings','Settings','الإعدادات']].map(([v,en,a])=><TabsTrigger key={v} value={v}>{tr(en,a)}</TabsTrigger>)}</TabsList><TabsContent value="overview"><div className="stat-grid"><Stat value={requests.length} label={['Total requests','إجمالي الطلبات']}/><Stat value={requests.filter((r:any)=>r.status==='Draft').length} label={['Drafts','المسودات']}/><Stat value={requests.filter((r:any)=>r.status==='Under Review').length} label={['Under review','قيد المراجعة']}/><Stat value={proposals.length} label={['Proposal versions','نسخ العروض']}/></div><div className="panel"><h2>{tr('Start with your requirements','ابدأ بمتطلباتك')}</h2><p>{tr('Request recruitment, outsourcing, staff augmentation or technical workforce support.','اطلب دعماً في التوظيف أو التعهيد أو دعم الفرق أو توفير القوى العاملة الفنية.')}</p><LinkButton href="/request-proposal">{tr('Create a proposal request','أنشئ طلب عرض')}</LinkButton></div><Notifications items={(dash.notifications||[]).slice(0,3)}/></TabsContent><TabsContent value="requests"><div className="panel"><div className="record-head"><h2>{tr('Requests & proposals','الطلبات والعروض')}</h2><LinkButton href="/request-proposal" small>{tr('New request','طلب جديد')}</LinkButton></div>{requests.length?requests.map((r:any)=><RequestCard key={r.id} r={r} proposals={proposals}/>):<p>{tr('No requests yet. Create your first proposal request.','لا توجد طلبات بعد. أنشئ أول طلب عرض.')}</p>}</div></TabsContent><TabsContent value="candidates"><div className="panel"><h2>{tr('Candidates shared by Apex','المرشحون الذين شاركتهم أبيكس')}</h2>{(dash.shares||[]).length?(dash.shares||[]).map((r:any)=><div className="record" key={r.id}><h3>{r.data.snapshot.name}</h3><p>{r.data.snapshot.email}</p><Info data={r.data.snapshot.profile}/><Files ids={[r.data.snapshot.profile.cvId]} label={tr('Download CV','تحميل السيرة')}/></div>):<p>{tr('No candidate profiles have been shared with your company.','لم تتم مشاركة ملفات مرشحين مع شركتك.')}</p>}</div></TabsContent><TabsContent value="profile"><Profile/></TabsContent><TabsContent value="notifications"><Notifications items={dash.notifications||[]}/></TabsContent><TabsContent value="settings"><AccountSettings/></TabsContent></Tabs>}
const vacancySpecs:Spec[]=[{k:'title',en:'Job title (English)',ar:'المسمى الوظيفي بالإنجليزية',required:true},{k:'titleAr',en:'Job title (Arabic)',ar:'المسمى الوظيفي بالعربية'},{k:'company',en:'Hiring company (optional)',ar:'الشركة الموظفة (اختياري)'},{k:'location',en:'Location',ar:'الموقع',required:true},{k:'industry',en:'Industry / department',ar:'القطاع أو القسم'},{k:'employmentType',en:'Employment type',ar:'نوع التوظيف',options:employment,required:true},{k:'arrangement',en:'Work arrangement',ar:'نظام العمل',options:arrangements,required:true},{k:'language',en:'Language requirements',ar:'متطلبات اللغة',required:true},{k:'shifts',en:'Shifts (if applicable)',ar:'الورديات إن وجدت'},{k:'deadline',en:'Application deadline (optional)',ar:'آخر موعد للتقديم (اختياري)',type:'date'},{k:'summary',en:'Short summary (English)',ar:'ملخص بالإنجليزية',type:'textarea'},{k:'summaryAr',en:'Short summary (Arabic)',ar:'ملخص بالعربية',type:'textarea'},{k:'responsibilities',en:'Responsibilities (English)',ar:'المسؤوليات بالإنجليزية',type:'textarea',required:true},{k:'responsibilitiesAr',en:'Responsibilities (Arabic)',ar:'المسؤوليات بالعربية',type:'textarea'},{k:'requirements',en:'Requirements (English)',ar:'المتطلبات بالإنجليزية',type:'textarea',required:true},{k:'requirementsAr',en:'Requirements (Arabic)',ar:'المتطلبات بالعربية',type:'textarea'},{k:'questionsText',en:'Screening questions (one per line)',ar:'أسئلة التقييم (سؤال في كل سطر)',type:'textarea',full:true},{k:'salary',en:'Authorised compensation details (optional)',ar:'تفاصيل التعويضات المصرح بها (اختياري)'},{k:'status',en:'Publication status',ar:'حالة النشر',options:[['Draft','Draft','مسودة'],['Published','Published','منشور'],['Closed','Closed','مغلق']]}];
function VacancyEditor({initial,onSaved}:{initial?:any;onSaved?:()=>void}){const {tr,mutate}=useA(),[d,setD]=useState<D>(initial?{...initial.data,status:initial.status,questionsText:(initial.data.questions||[]).join('\n')}:{status:'Draft',employmentType:'Full-time',arrangement:'On-site',questionsText:'',confidential:true,salaryAuthorised:false});return <form className="panel" onSubmit={e=>{e.preventDefault();mutate(async()=>{await api(initial?`vacancies/${initial.id}`:'vacancies',initial?'PUT':'POST',{...d,questions:d.questionsText.split('\n').map((s:string)=>s.trim()).filter(Boolean)});onSaved?.()},tr('Vacancy saved','تم حفظ الوظيفة'))}}><h2>{tr(initial?'Edit vacancy':'Create a real vacancy',initial?'تعديل الوظيفة':'إنشاء وظيفة حقيقية')}</h2><div className="notice warning">{tr('Publish only authorised, current vacancies. No demonstration roles are shown on the public website.','انشر وظائف حقيقية ومصرحاً بها فقط. لا تظهر وظائف تجريبية على الموقع العام.')}</div><Fields specs={vacancySpecs} data={d} set={setD}/><Tick checked={d.confidential} onChange={v=>setD({...d,confidential:v})}>{tr('Confidential recruitment: hide hiring-company identity.','توظيف سري: إخفاء هوية الشركة الموظفة.')}</Tick><Tick checked={d.salaryAuthorised} onChange={v=>setD({...d,salaryAuthorised:v})}>{tr('I am authorised to publish these compensation details.','أنا مخول بنشر تفاصيل التعويضات هذه.')}</Tick><Action type="submit">{tr('Save vacancy','احفظ الوظيفة')}</Action></form>}
function AdminVacancies(){const {tr,dash}=useA(),[edit,setEdit]=useState<any>(null),[create,setCreate]=useState(false);return <>{(edit||create)&&<VacancyEditor key={edit?.id||'new'} initial={edit||undefined} onSaved={()=>{setEdit(null);setCreate(false)}}/>}<div className="panel"><div className="record-head"><h2>{tr('Vacancy management','إدارة الوظائف')}</h2><Action small onClick={()=>{setEdit(null);setCreate(!create)}}>{tr(create?'Close editor':'Create vacancy',create?'إغلاق المحرر':'إنشاء وظيفة')}</Action></div>{(dash.vacancies||[]).length?dash.vacancies.map((r:any)=><div className="record" key={r.id}><div className="record-head"><h3>{r.data.title}</h3><Tag status={r.status}/></div><p>{r.data.location} · {r.data.arrangement}</p><div className="actions"><Action outline small onClick={()=>{setCreate(false);setEdit(r);window.scrollTo({top:0,behavior:'smooth'})}}>{tr('Edit / publish / close','تعديل / نشر / إغلاق')}</Action>{r.status==='Published'&&<LinkButton href={`/vacancies/${r.id}`} outline small>{tr('View public vacancy','عرض الوظيفة العامة')}</LinkButton>}</div></div>):<p>{tr('No vacancies yet. Add your first authorised role.','لا توجد وظائف بعد. أضف أول وظيفة مصرح بها.')}</p>}</div></>}
function TalentPool(){const {tr,dash}=useA(),[f,setF]=useState<D>({keyword:'',pool:'all'});const users=(dash.users||[]).filter((u:any)=>u.role==='candidate'&&(!f.keyword||`${u.name} ${u.profile.location} ${u.profile.skills} ${u.profile.languages} ${u.profile.preferredRoles}`.toLowerCase().includes(f.keyword.toLowerCase()))&&(f.pool==='all'||u.profile.talentPool===true));return <div className="panel"><h2>{tr('Candidates & talent pool','المرشحون وقاعدة الكفاءات')}</h2><Fields specs={[{k:'keyword',en:'Search name, skills, language, location or preferred role',ar:'ابحث بالاسم أو المهارات أو اللغة أو الموقع أو الوظيفة المفضلة'},{k:'pool',en:'Pool membership',ar:'عضوية قاعدة الكفاءات',options:[['all','All candidate accounts','كل حسابات المرشحين'],['pool','Talent pool only','قاعدة الكفاءات فقط']]}]} data={f} set={setF}/><LinkButton href="/api/export?scope=candidates" small outline>{tr('Export authorised candidates','تصدير المرشحين المخولين')}</LinkButton>{users.map((u:any)=><div className="record" key={u.id}><div className="record-head"><h3>{u.name}</h3>{u.profile.talentPool&&<span className="tag gold">{tr('Talent pool','قاعدة الكفاءات')}</span>}</div><p>{u.email} · {u.profile.location}</p><details className="details"><summary>{tr('Private candidate profile','ملف المرشح الخاص')}</summary><Info data={u.profile}/>{u.profile.cvId&&<Files ids={[u.profile.cvId]} label={tr('Download CV','تحميل السيرة')}/>}<InternalNotes parent={u.id}/></details></div>)}{!users.length&&<p className="mt-5">{tr('No matching candidates yet.','لا يوجد مرشحون مطابقون بعد.')}</p>}</div>}
function AdminApplications(){const {tr,dash}=useA(),[f,setF]=useState<D>({keyword:'',status:'all'});const list=(dash.applications||[]).filter((a:any)=>(!f.keyword||`${a.snapshot.name} ${a.vacancy.title}`.toLowerCase().includes(f.keyword.toLowerCase()))&&(!f.status||f.status==='all'||a.status===f.status));return <div className="panel"><div className="record-head"><h2>{tr('Applications','طلبات التوظيف')}</h2><LinkButton href="/api/export?scope=applications" small outline>{tr('Export applications','تصدير الطلبات')}</LinkButton></div><Fields specs={[{k:'keyword',en:'Candidate or vacancy',ar:'المرشح أو الوظيفة'},{k:'status',en:'Status',ar:'الحالة',options:[['all','All statuses','كل الحالات'],...applicationStatuses.map(s=>[s,s,statusAr[s]] as Opt)]}]} data={f} set={setF}/>{list.length?list.map((a:any)=><ApplicationCard a={a} key={a.id} staffView/>):<p>{tr('No matching applications.','لا توجد طلبات مطابقة.')}</p>}</div>}
function AdminClients(){const {tr,dash}=useA();return <div className="panel"><h2>{tr('Client accounts','حسابات العملاء')}</h2>{(dash.users||[]).filter((u:any)=>u.role==='client').map((u:any)=><div className="record" key={u.id}><h3>{u.profile.company||u.name}</h3><p>{u.name} · {u.email}</p><details className="details"><summary>{tr('Company profile','ملف الشركة')}</summary><Info data={{...u.profile,name:u.name}}/><InternalNotes parent={u.id}/></details></div>)}{!(dash.users||[]).some((u:any)=>u.role==='client')&&<p>{tr('No client accounts yet.','لا توجد حسابات عملاء بعد.')}</p>}</div>}
function ContentEditor(){const {tr,content,mutate}=useA(),[d,setD]=useState<D>(content);const specs:Spec[]=[{k:'headline',en:'Home headline (English)',ar:'عنوان الرئيسية بالإنجليزية'},{k:'headlineAr',en:'Home headline (Arabic)',ar:'عنوان الرئيسية بالعربية'},{k:'intro',en:'Home introduction (English)',ar:'مقدمة الرئيسية بالإنجليزية',type:'textarea'},{k:'introAr',en:'Home introduction (Arabic)',ar:'مقدمة الرئيسية بالعربية',type:'textarea'},{k:'about',en:'About text (English)',ar:'نص من نحن بالإنجليزية',type:'textarea'},{k:'aboutAr',en:'About text (Arabic)',ar:'نص من نحن بالعربية',type:'textarea'},...services.flatMap(s=>[{k:`service_${s.id}`,en:`${s.en} description (English)`,ar:`وصف ${s.ar} بالإنجليزية`,type:'textarea'},{k:`service_${s.id}_ar`,en:`${s.en} description (Arabic)`,ar:`وصف ${s.ar} بالعربية`,type:'textarea'}]),{k:'email',en:'Company email (not yet configured)',ar:'بريد الشركة (لم يتم إعداده بعد)',type:'email'},{k:'phone',en:'Telephone',ar:'الهاتف',type:'tel'},{k:'whatsapp',en:'WhatsApp with country code',ar:'واتساب مع رمز الدولة'},{k:'linkedin',en:'LinkedIn URL',ar:'رابط لينكد إن',type:'url'},{k:'facebook',en:'Facebook URL',ar:'رابط فيسبوك',type:'url'}];return <form className="panel" onSubmit={e=>{e.preventDefault();mutate(()=>api('content','PUT',d),tr('Website content saved','تم حفظ محتوى الموقع'))}}><h2>{tr('Website content & contact details','محتوى الموقع وبيانات التواصل')}</h2><p>{tr('Only publish company details and claims that are authorised and accurate. Leave unavailable contact fields empty.','انشر بيانات وادعاءات الشركة المصرح بها والدقيقة فقط. اترك بيانات التواصل غير المتوفرة فارغة.')}</p><Fields specs={specs} data={d} set={setD}/><Action type="submit">{tr('Save website content','احفظ محتوى الموقع')}</Action></form>}
function AdminEnquiries(){const {tr,dash,mutate}=useA();return <div className="panel"><h2>{tr('Business, candidate & training enquiries','استفسارات الشركات والمرشحين والتدريب')}</h2>{(dash.enquiries||[]).map((r:any)=><div className="record" key={r.id}><div className="record-head"><h3>{r.data.organisation||r.data.name}</h3><Tag status={r.status}/></div><p>{r.data.email} · {r.data.phone} · {r.data.type}</p><p className="white-space">{r.data.message}</p>{r.data.type==='training'&&<Info data={{roles:r.data.specialisations,skills:r.data.skills,location:r.data.locations,headcount:r.data.graduateNumbers}}/>}<InternalNotes parent={r.id}/><div className="actions"><Action outline small onClick={()=>mutate(()=>api(`enquiries/${r.id}`,'PUT',{status:r.status==='Pending'?'Resolved':'Pending'}),tr('Enquiry updated','تم تحديث الاستفسار'))}>{tr(r.status==='Pending'?'Mark resolved':'Reopen',r.status==='Pending'?'تحديد كمعالج':'إعادة الفتح')}</Action></div></div>)}{!(dash.enquiries||[]).length&&<p>{tr('No enquiries yet.','لا توجد استفسارات بعد.')}</p>}</div>}
function StaffPermissions(){const {tr,dash}=useA();return <div className="panel"><h2>{tr('Staff permissions','صلاحيات الموظفين')}</h2><div className="notice">{tr('Administrators manage all workflows. Recruiters can manage vacancies, candidate profiles and applications; client proposals and company settings remain administrator-only.','يدير المسؤولون كل سير العمل. يمكن لمسؤولي التوظيف إدارة الوظائف والمرشحين والطلبات، وتقتصر عروض العملاء وإعدادات الشركة على المسؤولين.')}</div>{(dash.users||[]).map((u:any)=><RoleEditor key={u.id} user={u}/>)}</div>}
function RoleEditor({user}:{user:any}){const {tr,mutate}=useA(),[d,setD]=useState<D>({role:user.role});return <div className="record"><h3>{user.name}</h3><p>{user.email}</p><div className="inline-form"><Field spec={{k:'role',en:'Account role',ar:'دور الحساب',options:[['admin','Administrator','مسؤول النظام'],['recruiter','Recruiter','مسؤول توظيف'],['client','Client','عميل'],['candidate','Candidate','مرشح']]}} data={d} set={setD}/><Action small onClick={()=>mutate(()=>api('staff','PUT',{id:user.id,role:d.role}),tr('Permissions updated','تم تحديث الصلاحيات'))}>{tr('Save role','حفظ الدور')}</Action></div></div>}
function AdminPrivacy(){const {tr,dash,mutate}=useA();return <div className="panel"><h2>{tr('Personal-data requests','طلبات البيانات الشخصية')}</h2>{(dash.privacy||[]).map((r:any)=>{const user=(dash.users||[]).find((u:any)=>u.id===r.owner);return <div className="record" key={r.id}><h3>{user?.name||tr('Account','حساب')}</h3><p>{user?.email} · {r.data.type==='delete'?tr('Account deletion request','طلب حذف الحساب'):tr('Data access assistance','مساعدة في الوصول للبيانات')}</p><Tag status={r.status}/>{r.status==='Pending'&&<div className="actions"><Action small outline onClick={()=>mutate(()=>api(`privacy/${r.id}`,'PUT',{}),tr('Request processed','تمت معالجة الطلب'))}>{r.data.type==='delete'?tr('Delete account & private data','حذف الحساب والبيانات الخاصة'):tr('Mark assistance resolved','تحديد المساعدة كمعالجة')}</Action></div>}</div>})}{!(dash.privacy||[]).length&&<p>{tr('No personal-data requests.','لا توجد طلبات بيانات شخصية.')}</p>}</div>}
function AdminReports(){const {tr,dash}=useA();const counts=(list:any[],statuses:string[])=>statuses.map(s=><div className="record-head py-3 border-b border-slate-200" key={s}><Tag status={s}/><strong>{list.filter((r:any)=>r.status===s).length}</strong></div>);return <><div className="admin-grid"><div className="panel"><h2>{tr('Recruitment activity','نشاط التوظيف')}</h2>{counts(dash.applications||[],applicationStatuses)}</div><div className="panel"><h2>{tr('Proposal activity','نشاط العروض')}</h2>{counts(dash.requests||[],['Draft',...proposalStatuses])}</div></div><div className="panel"><h2>{tr('Audit history','سجل المراجعة')}</h2>{(dash.audit||[]).map((r:any)=><div className="record" key={r.id}><strong>{r.action.replaceAll('_',' ')}</strong><p className="muted">{new Date(r.created).toLocaleString()} · {r.target}</p></div>)}{!(dash.audit||[]).length&&<p>{tr('Important actions will appear here.','ستظهر الإجراءات المهمة هنا.')}</p>}</div></>}
function StaffDashboard(){const {tr,dash,session}=useA(),[tab,setTab]=useState('overview'),isAdmin=session.user.role==='admin';const tabDefs=[['overview','Overview','نظرة عامة'],['vacancies','Vacancies','الوظائف'],['applications','Applications','الطلبات'],['talent','Talent pool','قاعدة الكفاءات'],...(isAdmin?[['clients','Clients','العملاء'],['requests','Proposals','العروض'],['enquiries','Enquiries','الاستفسارات'],['content','Website','الموقع'],['staff','Permissions','الصلاحيات'],['privacy','Data requests','طلبات البيانات'],['reports','Reports & audit','التقارير والمراجعة']]:[]),['notifications','Notifications','الإشعارات']];return <Tabs className="dash-tabs" value={tab} onValueChange={setTab}><TabsList>{tabDefs.map(([v,en,a])=><TabsTrigger key={v} value={v}>{tr(en,a)}</TabsTrigger>)}</TabsList><TabsContent value="overview"><div className="stat-grid"><Stat value={(dash.vacancies||[]).filter((r:any)=>r.status==='Published').length} label={['Published vacancies','وظائف منشورة']}/><Stat value={(dash.applications||[]).length} label={['Applications','الطلبات']}/><Stat value={(dash.users||[]).filter((u:any)=>u.role==='candidate'&&u.profile.talentPool).length} label={['Talent pool','قاعدة الكفاءات']}/><Stat value={(dash.requests||[]).filter((r:any)=>!['Draft','Accepted','Closed'].includes(r.status)).length} label={['Active proposal requests','طلبات عروض نشطة']}/></div><div className="panel"><h2>{tr('Apex administration','إدارة أبيكس')}</h2><p>{tr('Start with your real vacancies and company details. All reports use live records; no demonstration activity has been seeded.','ابدأ بالوظائف الحقيقية وبيانات الشركة. تعتمد التقارير على السجلات الفعلية، ولم تتم إضافة نشاط تجريبي.')}</p><div className="button-row"><Action onClick={()=>setTab('vacancies')}>{tr('Manage vacancies','إدارة الوظائف')}</Action>{isAdmin&&<Action outline onClick={()=>setTab('content')}>{tr('Set company details','إعداد بيانات الشركة')}</Action>}</div></div>{isAdmin&&<div className="notice warning">{tr('Launch setup: replace the temporary wordmark if you have a logo, add company contact details, review Privacy Policy and Terms, and configure EMAIL_API_KEY and EMAIL_FROM for transactional email.','إعداد الإطلاق: استبدل العلامة المؤقتة إن توفر شعار، أضف بيانات التواصل، راجع سياسة الخصوصية والشروط، وأعد EMAIL_API_KEY وEMAIL_FROM للبريد الإلكتروني.')}</div>}<div className="notice">{session.emailConfigured?tr('Transactional email configured.','تم إعداد البريد الإلكتروني.'):tr('Transactional email is not configured. Dashboard notifications work now.','لم يتم إعداد البريد الإلكتروني. إشعارات اللوحات تعمل حالياً.')}</div></TabsContent><TabsContent value="vacancies"><AdminVacancies/></TabsContent><TabsContent value="applications"><AdminApplications/></TabsContent><TabsContent value="talent"><TalentPool/></TabsContent>{isAdmin&&<><TabsContent value="clients"><AdminClients/><div className="panel"><h2>{tr('Active candidate shares','مشاركات المرشحين النشطة')}</h2>{(dash.shares||[]).filter((r:any)=>r.status==='Active').map((r:any)=><div className="record" key={r.id}><p>{r.data.snapshot.name} · {(dash.users||[]).find((u:any)=>u.id===r.owner)?.profile.company}</p><RevokeShare r={r}/></div>)}</div></TabsContent><TabsContent value="requests"><div className="panel"><h2>{tr('Client requests & proposals','طلبات العملاء والعروض')}</h2><LinkButton href="/api/export?scope=requests" small outline>{tr('Export business records','تصدير سجلات الأعمال')}</LinkButton>{(dash.requests||[]).filter((r:any)=>r.status!=='Draft').map((r:any)=><RequestCard key={r.id} r={r} proposals={dash.proposals||[]} adminView/>)}{!(dash.requests||[]).some((r:any)=>r.status!=='Draft')&&<p className="mt-5">{tr('No submitted requests yet. Client drafts remain private until submission.','لا توجد طلبات مرسلة بعد. تبقى مسودات العملاء خاصة حتى الإرسال.')}</p>}</div></TabsContent><TabsContent value="enquiries"><AdminEnquiries/></TabsContent><TabsContent value="content"><ContentEditor/></TabsContent><TabsContent value="staff"><StaffPermissions/></TabsContent><TabsContent value="privacy"><AdminPrivacy/></TabsContent><TabsContent value="reports"><AdminReports/></TabsContent></>}<TabsContent value="notifications"><Notifications items={dash.notifications||[]}/></TabsContent></Tabs>}
function RevokeShare({r}:{r:any}){const {tr,mutate}=useA();return <Action small outline onClick={()=>mutate(()=>api(`share/${r.id}`,'DELETE'),tr('Client access revoked','تم إلغاء وصول العميل'))}>{tr('Revoke access','إلغاء الوصول')}</Action>}
function Dashboard(){const {tr,session,loading,dash,error}=useA();if(loading)return <div className="loading">{tr('Loading your dashboard…','جارٍ تحميل لوحة التحكم…')}</div>;if(!session?.user)return <section className="section wrap narrow"><Empty title={['Sign in to your Apex account','سجل الدخول لحساب أبيكس']} desc={['Your dashboard contains private account records.','تحتوي اللوحة على سجلات حساب خاصة.']} href="/account" label={['Register / sign in','سجل حساباً / الدخول']}/></section>;return <section className="dashboard"><div className="dash-wrap" style={{gridTemplateColumns:'1fr'}}><div className="dash-main"><div className="dash-title"><div><h1>{['admin','recruiter'].includes(session.user.role)?tr('Apex workspace','مساحة عمل أبيكس'):tr('Your dashboard','لوحة التحكم')}</h1><p>{session.user.name} · {session.user.email}</p></div><SignOut/></div>{error&&<div className="notice error">{error}</div>}{dash?session.user.role==='candidate'?<CandidateDashboard/>:session.user.role==='client'?<ClientDashboard/>:<StaffDashboard/>:<div className="loading">{tr('Loading records…','جارٍ تحميل السجلات…')}</div>}</div></div></section>}
function Legal({type}:{type:'privacy'|'terms'}){const {tr}=useA();const privacy=[['Information we collect','المعلومات التي نجمعها','Account identity, contact and profile details, CVs, application answers, proposal requests and messages that you submit. We do not request national ID documents during basic registration.','هوية الحساب وبيانات التواصل والملف والسير الذاتية وإجابات التقديم وطلبات العروض والرسائل التي ترسلها. لا نطلب وثائق الهوية الوطنية في التسجيل الأساسي.'],['How information is used','كيفية استخدام المعلومات','To manage your account, assess recruitment suitability, process applications and proposal requests, respond to enquiries and maintain service records. Optional marketing consent is separate from activity notifications.','لإدارة حسابك وتقييم ملاءمتك للتوظيف ومعالجة الطلبات والعروض والرد على الاستفسارات وحفظ سجلات الخدمة. الموافقة التسويقية منفصلة عن إشعارات الأنشطة.'],['Access and sharing','الوصول والمشاركة','Candidate profiles and documents are private. Authorised Apex staff access information needed for their work. Candidate application information is shared with a client only through an authorised process and with the recorded consent for that application. Clients can view their own account records.','ملفات المرشحين ووثائقهم خاصة. يصل موظفو أبيكس المخولون للمعلومات اللازمة لعملهم. تُشارك معلومات الطلب مع العميل عبر إجراء مخول وبالموافقة المسجلة لذلك الطلب. يرى العملاء سجلات حساباتهم الخاصة.'],['Storage and service providers','التخزين ومقدمو الخدمات','The website uses hosted database and object storage. ChatGPT provides account authentication. If configured, an email delivery provider processes transactional messages. Company details, retention periods, provider disclosures and international-transfer arrangements require confirmation before public launch.','يستخدم الموقع قاعدة بيانات وتخزين ملفات مستضافين. يوفر ChatGPT مصادقة الحساب. عند الإعداد يعالج مزود البريد رسائل المعاملات. يجب تأكيد بيانات الشركة وفترات الاحتفاظ وإفصاحات المزودين وترتيبات نقل البيانات قبل الإطلاق العام.'],['Your requests','طلباتك','You can update your profile, withdraw eligible applications, download your records and request data assistance or account deletion in your dashboard. Contact Apex through the enquiry form for privacy questions. Deletion is processed by an authorised administrator; any required retention exceptions must be confirmed during legal review.','يمكنك تعديل ملفك وسحب الطلبات المؤهلة وتنزيل سجلاتك وطلب المساعدة بالبيانات أو حذف الحساب من اللوحة. تواصل مع أبيكس عبر نموذج الاستفسار لأسئلة الخصوصية. يعالج مسؤول مخول الحذف، ويجب تأكيد أي استثناءات للاحتفاظ أثناء المراجعة القانونية.'],['Browser storage','تخزين المتصفح','We use browser storage for your language choice and temporary proposal information entered before account registration. Saved account records are stored on the server. We do not add advertising trackers.','نستخدم تخزين المتصفح لاختيار اللغة والمعلومات المؤقتة للطلب قبل التسجيل. تُحفظ سجلات الحساب على الخادم. لا نضيف أدوات تتبع إعلانية.']];const terms=[['Using the website','استخدام الموقع','Provide accurate information and use the website for legitimate recruitment and business enquiries. Keep your sign-in account secure and submit only documents you are entitled to share.','قدم معلومات دقيقة واستخدم الموقع للاستفسارات المهنية والتجارية المشروعة. حافظ على أمان حساب الدخول وأرسل الوثائق التي يحق لك مشاركتها فقط.'],['Recruitment and applications','التوظيف والتقديم','Submitting an application or joining the talent pool does not guarantee an interview, employment or a particular outcome. Opportunities depend on employer requirements, available vacancies and selection.','إرسال طلب أو الانضمام لقاعدة الكفاءات لا يضمن مقابلة أو توظيفاً أو نتيجة محددة. تعتمد الفرص على متطلبات أصحاب العمل والوظائف المتاحة والاختيار.'],['Service proposals','عروض الخدمات','Proposal requests begin a discussion about scope, delivery and commercial arrangements. Accepting a proposal in the dashboard records the client’s response and does not automatically create a binding contract or initiate payment. A separate agreement may be required.','تبدأ طلبات العروض نقاشاً حول النطاق والتنفيذ والترتيبات التجارية. قبول العرض باللوحة يسجل رد العميل ولا ينشئ تلقائياً عقداً ملزماً أو يبدأ دفعاً. قد يلزم اتفاق منفصل.'],['Confidential information','المعلومات السرية','Respect the confidentiality of proposal documents, candidate information and any other private records made available through your account. Access is limited to authorised purposes.','احترم سرية وثائق العروض ومعلومات المرشحين وأي سجلات خاصة متاحة بحسابك. يقتصر الوصول على الأغراض المخولة.'],['Company and legal details','بيانات الشركة والتفاصيل القانونية','Apex Global Services LLC is the brand name supplied for this website. Registration details, jurisdiction, liability provisions, dispute procedures and final contractual terms are pending company confirmation and legal review. This draft does not state a country of incorporation.','Apex Global Services LLC هو الاسم التجاري المقدم لهذا الموقع. تفاصيل التسجيل والاختصاص والأحكام المتعلقة بالمسؤولية والنزاعات والشروط التعاقدية النهائية بانتظار تأكيد الشركة والمراجعة القانونية. لا تحدد هذه المسودة دولة تأسيس.']];return <><PageHeader en={type==='privacy'?'Privacy Policy':'Website Terms'} ar={type==='privacy'?'سياسة الخصوصية':'شروط الموقع'}/><section className="section"><div className="wrap narrow legal"><div className="notice warning">{tr('Draft for legal review before public launch. Company details and final legal wording require approval.','مسودة للمراجعة القانونية قبل الإطلاق العام. تتطلب بيانات الشركة والصياغة القانونية النهائية اعتماداً.')}</div><p className="muted">{tr('Version: 7 October 2026','النسخة: ٧ أكتوبر ٢٠٢٦')}</p>{(type==='privacy'?privacy:terms).map(([en,a,d,da])=><div key={en}><h2>{tr(en,a)}</h2><p>{tr(d,da)}</p></div>)}<a className="text-link" href="/contact">{tr('Contact Apex','تواصل مع أبيكس')}</a></div></section></>}
export function ApexApp({page,jobId}:{page:string;jobId?:string}){const [ar,setArabic]=useState(false),[session,setSession]=useState<any>(null),[publicData,setPublic]=useState<any>({content:defaultContent,vacancies:[]}),[dash,setDash]=useState<any>(null),[loading,setLoading]=useState(true),[error,setError]=useState(''),[busy,setBusy]=useState(false);const tr=(en:any,a:any)=>ar?a:en;const setAr=(v:boolean)=>{setArabic(v);localStorage.setItem('apex-language',v?'ar':'en');document.documentElement.lang=v?'ar':'en';document.documentElement.dir=v?'rtl':'ltr'};const refresh=async()=>{const s=await api('session');setSession(s);if(s.user)setDash(await api('dashboard'));const p=await api('public');setPublic(p)};useEffect(()=>{if(localStorage.getItem('apex-language')==='ar')setAr(true);Promise.allSettled([api('public'),api('session')]).then(async results=>{if(results[0].status==='fulfilled')setPublic(results[0].value);else setError(tr('Live information is temporarily unavailable. Please refresh shortly.','المعلومات المباشرة غير متاحة مؤقتاً. يرجى التحديث قريباً.'));if(results[1].status==='fulfilled'){setSession(results[1].value);if(results[1].value.user){try{setDash(await api('dashboard'))}catch(e:any){setError(e.message)}}}setLoading(false)})},[]);const mutate=async(fn:()=>Promise<any>,success:string)=>{setBusy(true);try{await fn();toast.success(success);await refresh();setError('')}catch(e:any){toast.error(ar?`تعذر إتمام الإجراء: ${e.message}`:e.message)}finally{setBusy(false)}};useEffect(()=>{const mc=(document as any).modelContext;if(!mc?.registerTool)return;const lifecycle=new AbortController();const settle=()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));if(page==='vacancies')Promise.resolve(mc.registerTool({name:'search_open_vacancies',title:'Search open vacancies',description:'Filter the visible live vacancy directory by keyword. Does not save or submit any application.',inputSchema:{type:'object',properties:{keyword:{type:'string',maxLength:200}},required:['keyword'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},async execute(input:any){if(typeof input?.keyword!=='string'||input.keyword.length>200||Object.keys(input).length!==1)throw new Error('Provide a keyword of at most 200 characters.');window.dispatchEvent(new CustomEvent('apex-vacancy-search',{detail:{keyword:input.keyword}}));await settle();return {matches:publicData.vacancies.filter((j:any)=>`${j.data.title} ${j.data.requirements} ${j.data.responsibilities}`.toLowerCase().includes(input.keyword.toLowerCase())).map((j:any)=>({id:j.id,title:j.data.title,location:j.data.location}))}}},{signal:lifecycle.signal})).catch(()=>{});if(page==='request-proposal')Promise.resolve(mc.registerTool({name:'stage_proposal_request',title:'Stage proposal request',description:'Fill the visible proposal form with temporary draft details. This does not submit the request, upload files, or create an account.',inputSchema:{type:'object',properties:{service:{type:'string',enum:['recruitment','outsourcing','augmentation','industrial','other']},company:{type:'string',maxLength:200},roles:{type:'string',maxLength:2000}},required:['service'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},async execute(input:any){if(!input||!['recruitment','outsourcing','augmentation','industrial','other'].includes(input.service)||Object.keys(input).some(k=>!['service','company','roles'].includes(k))||Object.entries(input).some(([k,v])=>typeof v!=='string'||(v as string).length>(k==='roles'?2000:200)))throw new Error('Invalid proposal draft details.');window.dispatchEvent(new CustomEvent('apex-stage-proposal',{detail:input}));await settle();return {staged:true,submitted:false}}},{signal:lifecycle.signal})).catch(()=>{});return()=>lifecycle.abort()},[page,publicData.vacancies]);const ctx={ar,setAr,tr,session,dash,loading,error,busy,mutate,content:publicData.content,jobs:publicData.vacancies};return <Context.Provider value={ctx}><div dir={ar?'rtl':'ltr'}><Header page={page}/><main id="main-content">{error&&!['dashboard','admin'].includes(page)&&<div className="wrap"><div role="alert" className="notice error">{error}</div></div>}{page==='home'?<Home/>:page==='about'?<About/>:page==='services'?<Services/>:page==='vacancies'?<Vacancies/>:page==='job'?<JobDetail jobId={jobId!}/>:page==='account'?<Account/>:page==='request-proposal'?<RequestProposal/>:page==='partnerships'?<Partnerships/>:page==='contact'?<Contact/>:['dashboard','admin'].includes(page)?<Dashboard/>:page==='privacy'?<Legal type="privacy"/>:<Legal type="terms"/>}</main><Footer/><Toaster position="bottom-center" dir={ar?'rtl':'ltr'} richColors/></div></Context.Provider>}
